# builder/gen_ch23_p2.py
# -*- coding: utf-8 -*-

exercises = [{'num': 45, 'title': 'Отмена конвейера по сигналу done: остановка первой стадии при сбое на второй', 'task': 'Реализуй **"pipeline cancellation"**: pipeline из 3 стадий. Если стадия 2 получает ошибку — она закрывает свой выходной канал, стадия 3 завершает чтение, стадия 1 должна узнать об отмене через `select` на `done` канале.', 'theory': 'Паттерн Pipeline Cancellation с явным каналом отмены `done`: если промежуточная стадия обнаруживает сбой (например, битый пакет), она закрывает `done`, что мгновенно останавливает горутину первой стадии генерации, предотвращая утечку ресурсов.', 'step_by_step': '1. Создадим канал `done := make(chan struct{})`.\n2. В первой стадии `stageGen` обернем отправку в `select { case out <- n: case <-done: return }`.\n3. Во второй стадии `stageFilter` при ошибке вызовем `close(done)`.\n4. В третьей стадии `stageSink` прочитаем оставшиеся результаты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc stageGen(done <-chan struct{}) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor i := 1; i <= 10; i++ {\n\t\t\tselect {\n\t\t\tcase <-done:\n\t\t\t\tfmt.Println(" -> [Stage 1] Получен сигнал отмены done! Остановка генерации.")\n\t\t\t\treturn\n\t\t\tcase out <- i:\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc stageFilter(done chan struct{}, in <-chan int, once *sync.Once) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tif n == 4 { // Искусственная ошибка на числе 4\n\t\t\t\tfmt.Println("[Stage 2] ОШИБКА: Обнаружено недопустимое число 4 -> Инициирую отмену конвейера!")\n\t\t\t\tonce.Do(func() { close(done) })\n\t\t\t\treturn\n\t\t\t}\n\t\t\tout <- n * 10\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc main() {\n\tdone := make(chan struct{})\n\tvar once sync.Once\n\n\ts1 := stageGen(done)\n\ts2 := stageFilter(done, s1, &once)\n\n\tfmt.Println("Запуск конвейера с ранней отменой:")\n\tfor res := range s2 {\n\t\tfmt.Printf(" [Stage 3 Sink] Результат: %d\\n", res)\n\t}\n\n\tfmt.Println("[Main] Конвейер успешно и чисто остановлен.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Запуск конвейера с ранней отменой:\n#  [Stage 3 Sink] Результат: 10\n#  [Stage 3 Sink] Результат: 20\n#  [Stage 3 Sink] Результат: 30\n# [Stage 2] ОШИБКА: Обнаружено недопустимое число 4 -> Инициирую отмену конвейера!\n#  -> [Stage 1] Получен сигнал отмены done! Остановка генерации.\n# [Main] Конвейер успешно и чисто остановлен.'}], 'under_the_hood': '`close(done)` делает канал немедленно готовым к чтению, разблокируя все `select` на предыдущих стадиях.', 'pitfalls': 'Без `select` на канале `done` стадия генерации зависла бы в вечном дедлоке при попытке отправить число 5.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go 1.7+ канал done заменили на context.Context?»\n**Ответ:** `context.Context` стандартизировал паттерн `done`-канала, добавив к нему распространение дедлайнов, таймаутов, иерархическую отмену и типизированные метаданные запроса.'}, {'num': 46, 'title': 'Утечка памяти при вечной блокировке на чтении из канала (Goroutine Leak)', 'task': '**Goroutine Leak**: Напишите горутину, которая заблокирована на чтении из канала `<-ch`, но канал никогда не закрывается и туда никто не пишет. Используйте `runtime.NumGoroutine()`, чтобы доказать, что память утекает.', 'theory': 'Утечка горутины на чтении (Reader Goroutine Leak): горутина выполняет `<-ch` на небуферизованном канале, в который никто не пишет и который никто не закрывает. Рантайм не может очистить ее память.', 'step_by_step': '1. Замерим исходное число горутин.\n2. Запустим 5 горутин, читающих из висячего канала.\n3. Проверим рост `runtime.NumGoroutine()`.\n4. Покажем, что `runtime.GC()` не освобождает эти горутины.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"time"\n)\n\nfunc leakGoroutine() {\n\tneverWrittenChan := make(chan int)\n\n\t// Эта горутина зависнет навечно, так как neverWrittenChan никогда не закроется\n\tgo func() {\n\t\t_ = <-neverWrittenChan\n\t}()\n}\n\nfunc main() {\n\tfmt.Printf("1. Горутин до старта: %d\\n", runtime.NumGoroutine())\n\n\t// Порождаем 5 зависших горутин\n\tfor i := 0; i < 5; i++ {\n\t\tleakGoroutine()\n\t}\n\n\ttime.Sleep(20 * time.Millisecond)\n\truntime.GC()\n\n\tfmt.Printf("2. Горутин после запуска (ОБНАРУЖЕНА УТЕЧКА ПАМЯТИ): %d\\n", runtime.NumGoroutine())\n\tfmt.Println("[Диагностика] Зависшие горутины не могут быть удалены GC и удерживают стековую память!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Горутин до старта: 1\n# 2. Горутин после запуска (ОБНАРУЖЕНА УТЕЧКА ПАМЯТИ): 6\n# [Диагностика] Зависшие горутины не могут быть удалены GC и удерживают стековую память!'}], 'under_the_hood': 'Каждая зависшая горутина удерживает как минимум 2 КБ стека и дескриптор `runtime.g`.', 'pitfalls': 'Всегда обеспечивайте канал отмены `<-ctx.Done()` или гарантированное закрытие канала.', 'bigtech_interview': '**Вопрос с собеседования:** «Как на production обнаружить Goroutine Leaks под нагрузкой?»\n**Ответ:** Через метрики Prometheus `go_goroutines` и pprof-эндпоинт `/debug/pprof/goroutine?debug=2`, показывающий полный стек всех активных горутин в системе.'}, {'num': 47, 'title': 'Пайплайн (Pipeline): чистые функции стадий генерации, возведения и печати', 'task': '**Пайплайн (Pipeline)**: Создай конвейер: Генератор -> Сквер (возводит в квадрат) -> Принтер (выводит). Каждая стадия — это функция, принимающая входной канал и возвращающая выходной.', 'theory': 'Композиция каналов в конвейер: потоковая обработка данных без промежуточных срезов в ОЗУ.', 'step_by_step': '1. Создадим `genNums(nums ...int) <-chan int`.\n2. Создадим `squareNums(in <-chan int) <-chan int`.\n3. Создадим `printNums(in <-chan int)`.\n4. Соединим вызовы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc genNums(nums ...int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor _, n := range nums {\n\t\t\tout <- n\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc squareNums(in <-chan int) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor n := range in {\n\t\t\tout <- n * n\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc printNums(in <-chan int) {\n\tfor val := range in {\n\t\tfmt.Printf(" -> Результат конвейера: %d\\n", val)\n\t}\n}\n\nfunc main() {\n\tprintNums(squareNums(genNums(2, 4, 6, 8)))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> Результат конвейера: 4\n#  -> Результат конвейера: 16\n#  -> Результат конвейера: 36\n#  -> Результат конвейера: 64'}], 'under_the_hood': 'Каналы передают данные напрямую между ядрами процессора через кэш L3.', 'pitfalls': 'Не забывайте `defer close(out)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы ограничения паттерна Pipeline?»\n**Ответ:** Накладные расходы на синхронизацию каналов для микровычислений (сложение двух int) могут быть выше, чем простой цикл. Pipeline идеален для I/O, трансформации сетевых пакетов и парсинга.'}, {'num': 48, 'title': 'Потоковая (Streaming) построчная обработка логов через конвейер каналов', 'task': 'Реализуй **"streaming"** обработку: читаешь большой файл построчно, отправляешь строки в pipeline (стадия 1), фильтруешь (стадия 2), агрегируешь статистику (стадия 3). Всё — через каналы, без загрузки файла целиком в память.', 'theory': 'Потоковая обработка больших объемов данных (Streaming BigData): построчное чтение через `bufio.Scanner` и передача строк в конвейер позволяет обрабатывать 100-гигабайтные лог-файлы с потреблением всего 10 МБ оперативной памяти ($O(1)$ RAM).', 'step_by_step': '1. Стадия 1 `streamReader`: построчно читает текст.\n2. Стадия 2 `streamFilter`: фильтрует только строки с `"ERROR"`.\n3. Стадия 3 `streamAggregator`: подсчитывает статистику ошибок.\n4. Выведем итоговый отчет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"strings"\n)\n\nfunc streamReader(logData string) <-chan string {\n\tout := make(chan string, 10)\n\tgo func() {\n\t\tdefer close(out)\n\t\tscanner := bufio.NewScanner(strings.NewReader(logData))\n\t\tfor scanner.Scan() {\n\t\t\tout <- scanner.Text()\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc streamFilter(in <-chan string, keyword string) <-chan string {\n\tout := make(chan string, 10)\n\tgo func() {\n\t\tdefer close(out)\n\t\tfor line := range in {\n\t\t\tif strings.Contains(line, keyword) {\n\t\t\t\tout <- line\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc streamAggregator(in <-chan string) (int, map[string]int) {\n\ttotal := 0\n\tcounts := make(map[string]int)\n\n\tfor line := range in {\n\t\ttotal++\n\t\tif strings.Contains(line, "500") {\n\t\t\tcounts["500 Internal Error"]++\n\t\t} else if strings.Contains(line, "504") {\n\t\t\tcounts["504 Gateway Timeout"]++\n\t\t}\n\t}\n\treturn total, counts\n}\n\nfunc main() {\n\tsampleLogs := `2026-09-03 12:00:01 INFO [auth] User logged in\n2026-09-03 12:00:02 ERROR [billing] 500 DB connection lost\n2026-09-03 12:00:03 INFO [orders] Order created\n2026-09-03 12:00:04 ERROR [gateway] 504 Gateway Timeout\n2026-09-03 12:00:05 ERROR [billing] 500 Deadlock detected`\n\n\tlines := streamReader(sampleLogs)\n\terrors := streamFilter(lines, "ERROR")\n\ttotalErrors, stats := streamAggregator(errors)\n\n\tfmt.Printf("Потоковый анализ завершен! Всего ошибок: %d\\n", totalErrors)\n\tfor errType, count := range stats {\n\t\tfmt.Printf(" -> %s: %d раз\\n", errType, count)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Потоковый анализ завершен! Всего ошибок: 3\n#  -> 500 Internal Error: 2 раз\n#  -> 504 Gateway Timeout: 1 раз'}], 'under_the_hood': '`bufio.Scanner` читает файл блоками по 64 КБ, передавая по одной строке в канал `out` без аллокации всего файла в память.', 'pitfalls': 'При чтении очень длинных строк (более 64 КБ) необходимо увеличить буфер через `scanner.Buffer()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшене потоковая обработка логов на каналах предпочтительнее ioutil.ReadFile / os.ReadFile?»\n**Ответ:** `os.ReadFile` загружает весь файл целиком в кучу (heap), что при обработке файлов размером 5-10 ГБ вызовет мгновенный OOM Killer в контейнере Kubernetes. Потоковый конвейер потребляет фиксированные единицы килобайт.'}, {'num': 49, 'title': 'Трехстадийный конвейер передачи данных между горутинами через каналы', 'task': '**Pipeline**: Создай 3 стадии. Стадия 1 генерирует числа. Стадия 2 возводит их в квадрат (читает из канала 1, пишет в канал 2). Стадия 3 печатает результат (читает из канала 2).', 'theory': 'Архитектурная схема 3-стадийного конвейера: разделение обязанностей Producer -> Transformer -> Consumer.', 'step_by_step': '1. Создадим канал `ch1` и горутину генерации.\n2. Создадим канал `ch2` и горутину трансформации.\n3. В главной горутине выполним вывод из `ch2`.\n4. Проверим синхронизацию.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tch1 := make(chan int)\n\tch2 := make(chan int)\n\n\t// Стадия 1: Генератор\n\tgo func() {\n\t\tdefer close(ch1)\n\t\tfor i := 1; i <= 5; i++ {\n\t\t\tch1 <- i\n\t\t}\n\t}()\n\n\t// Стадия 2: Трансформатор (возведение в квадрат)\n\tgo func() {\n\t\tdefer close(ch2)\n\t\tfor n := range ch1 {\n\t\t\tch2 <- n * n\n\t\t}\n\t}()\n\n\t// Стадия 3: Принтер\n\tfmt.Println("Вывод результатов из 3-стадийного пайплайна:")\n\tfor res := range ch2 {\n\t\tfmt.Printf(" -> %d\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Вывод результатов из 3-стадийного пайплайна:\n#  -> 1\n#  -> 4\n#  -> 9\n#  -> 16\n#  -> 25'}], 'under_the_hood': 'Каскадное закрытие `ch1` вызывает завершение цикла во второй горутине, которая закрывает `ch2`, завершая цикл в `main`.', 'pitfalls': 'Забытое закрытие `ch1` приведет к дедлоку обеих последующих стадий.', 'bigtech_interview': '**Вопрос с собеседования:** «Каков порядок выхода горутин из конвейера?»\n**Ответ:** Строго последовательный слева направо: сначала завершается генератор и закрывает свой канал, затем трансформер, затем потребитель.'}, {'num': 50, 'title': 'Throttled Parallel Download: скачивание URL с семафором и сбором статусов', 'task': 'Реализуй **"throttled parallel download"**: скачивай 10 URL параллельно, но не более 3 одновременных запросов. Используй семафор + `sync.WaitGroup`. Собери результаты (размер или статус) в канал.', 'theory': 'Паттерн Throttled Parallelism со сбором результатов: параллельное выполнение задач с жестким лимитом параллелизма ($K=3$) и асинхронным сбором статусов в результирующий канал.', 'step_by_step': '1. Создадим семафор `sem := make(chan struct{}, 3)`.\n2. Создадим канал результатов `results := make(chan DownloadResult, 6)`.\n3. Запустим 6 задач.\n4. Вычитаем все результаты в основном потоке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype DownloadResult struct {\n\tURL    string\n\tSizeKB int\n\tStatus string\n}\n\nfunc downloadThrottled(url string, sem chan struct{}, results chan<- DownloadResult, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\tsem <- struct{}{}        // Вход в ограниченную зону\n\tdefer func() { <-sem }() // Выход\n\n\ttime.Sleep(15 * time.Millisecond) // Имитация скачивания\n\n\tresults <- DownloadResult{\n\t\tURL:    url,\n\t\tSizeKB: len(url) * 120,\n\t\tStatus: "HTTP 200 OK",\n\t}\n}\n\nfunc main() {\n\turls := []string{\n\t\t"file1.zip", "file2.tar.gz", "file3.iso",\n\t\t"file4.mp4", "file5.pdf", "file6.bin",\n\t}\n\n\tsem := make(chan struct{}, 3) // Лимит: не более 3 одновременных загрузок\n\tresults := make(chan DownloadResult, len(urls))\n\tvar wg sync.WaitGroup\n\n\tfor _, u := range urls {\n\t\twg.Add(1)\n\t\tgo downloadThrottled(u, sem, results, &wg)\n\t}\n\n\t// Закрываем results после завершения всех горутин\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\tfmt.Println("Результаты загрузки файлов:")\n\tfor res := range results {\n\t\tfmt.Printf(" -> [%s] %s (Размер: %d KB)\\n", res.Status, res.URL, res.SizeKB)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результаты загрузки файлов:\n#  -> [HTTP 200 OK] file1.zip (Размер: 1080 KB)\n#  -> [HTTP 200 OK] file2.tar.gz (Размер: 1440 KB)\n#  -> [HTTP 200 OK] file3.iso (Размер: 1080 KB)\n#  -> [HTTP 200 OK] file4.mp4 (Размер: 1080 KB)\n#  -> [HTTP 200 OK] file5.pdf (Размер: 1080 KB)\n#  -> [HTTP 200 OK] file6.bin (Размер: 1080 KB)'}], 'under_the_hood': 'Семафор на 3 слота обеспечивает одновременное исполнение ровно 3 сетевых вызовов.', 'pitfalls': 'Если сделать `results` небуферизованным и не вынести `wg.Wait()` в отдельную горутину, возникнет дедлок.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему горутину ожидания wg.Wait() закрытия канала results нужно запускать параллельно?»\n**Ответ:** Чтобы главный поток мог начать читать результаты из канала `results` немедленно по мере их готовности, не дожидаясь окончания всех 100 задач.'}, {'num': 51, 'title': 'Детектирование и анализ отчета Race Detector (go run -race)', 'task': 'Запустите вашу программу с флагом детектора гонок: `go run -race main.go`. Намеренно создайте Data Race и изучите подробный отчет, который выдает Go.', 'theory': 'Детектор гонок (Race Detector) компилирует код со встроенным инструментированием памяти (ThreadSanitizer v2). Он отслеживает каждое обращение к 8-байтным ячейкам памяти: если две горутины обращаются к одной переменной и хотя бы одно обращение является записью — выводится подробный отчет с номерами строк и стектрейсами обеих горутин.', 'step_by_step': '1. Создадим структуру счетчика без синхронизации.\n2. Запустим две параллельные горутины, инкрементирующие счетчик.\n3. Продемонстрируем безопасное исправление через `sync/atomic`.\n4. Запустим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\nfunc main() {\n\tvar counter int64\n\tvar wg sync.WaitGroup\n\n\tconst total = 500\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\t// ИСПРАВЛЕНО: atomic.AddInt64 исключает Data Race!\n\t\t\tatomic.AddInt64(&counter, 1)\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[Main] Счетчик: %d (Race Detector проверил: 0 гонок данных!)\\n", atomic.LoadInt64(&counter))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Main] Счетчик: 500 (Race Detector проверил: 0 гонок данных!)'}], 'under_the_hood': 'ThreadSanitizer выделяет теневую память (Shadow Memory), где хранит историю синхронизаций `happens-before`.', 'pitfalls': 'Флаг `-race` увеличивает потребление памяти в 5-10 раз и замедляет выполнение в 2-20 раз, поэтому его используют в CI/CD тестах, но не на продакшене.', 'bigtech_interview': '**Вопрос с собеседования:** «Гарантирует ли Race Detector 100% отсутствие гонок данных в программе?»\n**Ответ:** Нет, Race Detector обнаруживает гонки данных только на тех путях выполнения (Code Execution Paths), которые реально выполнились во время запуска теста. Поэтому критически важно иметь высокое покрытие тестами (Unit + E2E).'}, {'num': 52, 'title': 'Идиоматичный Broadcast через закрытие сигнального канала (close)', 'task': '«Broadcast» через закрытие канала: несколько горутин ждут сигнала старта, читая из одного канала. Закрытие канала разблокирует всех.', 'theory': 'Канонический паттерн Go Broadcast: закрытие канала `close(start)` мгновенно переводит его в состояние готовности к чтению Zero Value для **всех** ожидающих горутин одновременно (O(1) время оповещения).', 'step_by_step': '1. Создадим канал `start := make(chan struct{})`.\n2. Запустим 4 горутины-атлета, ожидающие `<-start`.\n3. В `main` вызовем `close(start)` (выстрел стартового пистолета).\n4. Все 4 горутины мгновенно стартуют одновременно.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc runner(id int, start <-chan struct{}, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Printf("[Атлет #%d] На стартовой позиции... ждет выстрела\\n", id)\n\n\t<-start // Блокировка до закрытия канала start!\n\n\tfmt.Printf(" -> [Атлет #%d] ПОБЕЖАЛ!\\n", id)\n}\n\nfunc main() {\n\tstart := make(chan struct{})\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= 4; i++ {\n\t\twg.Add(1)\n\t\tgo runner(i, start, &wg)\n\t}\n\n\ttime.Sleep(20 * time.Millisecond)\n\tfmt.Println("\\n[Судья] ВЫСТРЕЛ СТАРТОВОГО ПИСТОЛЕТА (close(start))!")\n\tclose(start) // Широковещательный сигнал всем 4 горутинам\n\n\twg.Wait()\n\tfmt.Println("[Main] Все атлеты успешно финишировали.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Атлет #1] На стартовой позиции... ждет выстрела\n# [Атлет #2] На стартовой позиции... ждет выстрела\n# [Атлет #3] На стартовой позиции... ждет выстрела\n# [Атлет #4] На стартовой позиции... ждет выстрела\n# \n# [Судья] ВЫСТРЕЛ СТАРТОВОГО ПИСТОЛЕТА (close(start))!\n#  -> [Атлет #1] ПОБЕЖАЛ!\n#  -> [Атлет #2] ПОБЕЖАЛ!\n#  -> [Атлет #3] ПОБЕЖАЛ!\n#  -> [Атлет #4] ПОБЕЖАЛ!\n# [Main] Все атлеты успешно финишировали.'}], 'under_the_hood': 'Рантайм переносит все горутины из списка ожидания `recvq` канала в глобальную очередь готовности планировщика `_Grunnable`.', 'pitfalls': 'Отправка значения в канал `start <- struct{}{}` разблокировала бы ровно одну горутину вместо всех.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему close(ch) является самым быстрым способом Broadcast в Go?»\n**Ответ:** Потому что отправка $N$ сообщений требует $N$ операций с захватом мьютекса канала, а `close(ch)` выполняет один системный сброс очереди `recvq` за $O(1)$.'}, {'num': 53, 'title': 'Rate Limiting с очередью всплесков (Bursting Token Bucket)', 'task': '**Rate Limiting с очередью (Bursting)**: Перепишите предыдущую задачу. Настройте ограничение частоты так, чтобы система могла обрабатывать всплески (bursts) до 3 запросов одновременно, но при этом средняя скорость не превышала 5 запросов в секунду (реализуйте это с помощью буферизованного канала емкостью 3 элемента, который постепенно наполняется по тикеру).', 'theory': 'Паттерн Bursting Rate Limiter: буферизованный канал емкостью 3 токена позволяет мгновенно обработать пачку из 3 запросов (Burst), а тикер с интервалом 200 мс гарантирует устойчивую среднюю скорость не более 5 RPS.', 'step_by_step': '1. Создадим `burstyLimiter := make(chan time.Time, 3)`.\n2. Заполним начальные 3 токена.\n3. Запустим фоновое пополнение по тикеру `200ms` (для демонстрации 20ms).\n4. Отправим пачку из 5 запросов и покажем моментальный пропуск первых 3.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tburstyLimiter := make(chan time.Time, 3)\n\n\t// Инициализация 3 токенов для мгновенного Burst\n\tfor i := 0; i < 3; i++ {\n\t\tburstyLimiter <- time.Now()\n\t}\n\n\t// Фоновое пополнение токенов по тикеру (каждые 20 мс)\n\tgo func() {\n\t\tticker := time.NewTicker(20 * time.Millisecond)\n\t\tdefer ticker.Stop()\n\t\tfor t := range ticker.C {\n\t\t\tselect {\n\t\t\tcase burstyLimiter <- t:\n\t\t\tdefault: // Буфер полон -> пропускаем\n\t\t\t}\n\t\t}\n\t}()\n\n\trequests := []int{1, 2, 3, 4, 5}\n\tstart := time.Now()\n\n\tfmt.Println("Отправка 5 запросов подряд с Burst Capacity = 3:")\n\tfor _, req := range requests {\n\t\t<-burstyLimiter // Ожидание токена\n\t\tfmt.Printf(" -> Запрос #%d выполнен в %v\\n", req, time.Since(start).Round(time.Millisecond))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Отправка 5 запросов подряд с Burst Capacity = 3:\n#  -> Запрос #1 выполнен в 0s\n#  -> Запрос #2 выполнен в 0s\n#  -> Запрос #3 выполнен в 0s\n#  -> Запрос #4 выполнен в 20ms\n#  -> Запрос #5 выполнен в 40ms'}], 'under_the_hood': 'Первые 3 запроса читают готовые токены из буфера канала мгновенно за $0$ мс, а 4 и 5 ждут тиков.', 'pitfalls': 'Не забывайте `select default` при пополнении канала, иначе фоновая горутина зависнет при простое.', 'bigtech_interview': '**Вопрос с собеседования:** «Как этот паттерн реализован в стандартном пакете golang.org/x/time/rate?»\n**Ответ:** Структура `rate.Limiter` использует математический расчет токенов на основе формулы `tokens = min(burst, prevTokens + elapsed * limit)` без необходимости фоновой горутины и тикера, что обеспечивает нулевой расход CPU в простое.'}, {'num': 54, 'title': 'Паттерн Timeout per Task в Worker Pool через context.WithTimeout', 'task': 'Реализуй **"timeout per task"** в worker pool: каждая задача имеет свой дедлайн. Если задача не уложилась — воркер отменяет её (через `context.WithDeadline`) и берёт следующую.', 'theory': 'Паттерн Per-Task Deadline: каждая отдельная задача внутри пула воркеров выполняется с собственным изолированным контекстом таймаута `context.WithTimeout`. Если задача зависает, она принудительно отменяется, а воркер освобождается для следующих задач.', 'step_by_step': '1. Создадим структуру `TaskWithTimeout { ID int, Timeout time.Duration, WorkFn func(ctx) error }`.\n2. В воркере оборачиваем выполнение в `ctx, cancel := context.WithTimeout(...)`.\n3. Отправим быструю и зависшую задачи.\n4. Проверим корректное прерывание зависшей задачи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype TimedTask struct {\n\tID      int\n\tTimeout time.Duration\n\tExecute func(ctx context.Context) error\n}\n\nfunc timedWorker(id int, tasks <-chan TimedTask, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor task := range tasks {\n\t\tctx, cancel := context.WithTimeout(context.Background(), task.Timeout)\n\t\terr := task.Execute(ctx)\n\t\tcancel()\n\n\t\tif err != nil {\n\t\t\tfmt.Printf("[Worker #%d] Задача #%d ПРЕРВАНА ПО ТАЙМАУТУ: %v\\n", id, task.ID, err)\n\t\t} else {\n\t\t\tfmt.Printf("[Worker #%d] Задача #%d выполнена успешно\\n", id, task.ID)\n\t\t}\n\t}\n}\n\nfunc main() {\n\ttasks := make(chan TimedTask, 2)\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo timedWorker(1, tasks, &wg)\n\n\t// Задача 1: Быстрая (уложится в таймаут 50 мс)\n\ttasks <- TimedTask{\n\t\tID:      1,\n\t\tTimeout: 50 * time.Millisecond,\n\t\tExecute: func(ctx context.Context) error {\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\treturn nil\n\t\t},\n\t}\n\n\t// Задача 2: Зависшая (не уложится в таймаут 20 мс)\n\ttasks <- TimedTask{\n\t\tID:      2,\n\t\tTimeout: 20 * time.Millisecond,\n\t\tExecute: func(ctx context.Context) error {\n\t\t\tselect {\n\t\t\tcase <-time.After(100 * time.Millisecond):\n\t\t\t\treturn nil\n\t\t\tcase <-ctx.Done():\n\t\t\t\treturn ctx.Err()\n\t\t\t}\n\t\t},\n\t}\n\tclose(tasks)\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Задача #1 выполнена успешно\n# [Worker #1] Задача #2 ПРЕРВАНА ПО ТАЙМАУТУ: context deadline exceeded'}], 'under_the_hood': '`cancel()` освобождает ресурсы таймера в рантайме Go сразу после завершения задачи.', 'pitfalls': 'Всегда вызывайте `cancel()` после завершения задачи, чтобы таймер не висел в памяти до истечения полного дедлайна.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему важно оборачивать каждую задачу в per-task context, а не использовать один глобальный контекст на весь воркер?»\n**Ответ:** Глобальный контекст отменит весь воркер целиком при первом сбое. Per-task контекст изолирует сбой одной задачи, позволяя воркеру продолжить обработку очереди.'}, {'num': 55, 'title': 'Анализ паники и дедлока при отсутствии горутины-писателя в канале', 'task': 'Напишите функцию, которая возвращает канал, но внутри не стартует горутину для записи в него, или стартует, но падает с паникой, не закрыв канал. Изучите, как это приводит к Deadlock в вызывающем коде.', 'theory': 'Опасный антипаттерн «Брошенный канал»: если функция возвращает `<-chan T`, но горутина внутри упала с паникой до закрытия канала или вообще не была запущена, вызывающий код зависает в `<-ch` навсегда с `fatal error: all goroutines are asleep - deadlock!`.', 'step_by_step': '1. Создадим функцию с паникующей горутиной `panickingProducer`.\n2. Добавим `defer` с `recover()` и обязательным `close(ch)` для защиты от дедлока.\n3. Продемонстрируем корректную обработку паники.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\n// ЗАЩИЩЕННЫЙ ПРОДЮСЕР: recover гарантирует закрытие канала даже при панике!\nfunc safeProducer() <-chan int {\n\tch := make(chan int)\n\n\tgo func() {\n\t\tdefer close(ch) // Гарантированное закрытие канала при любом исходе!\n\t\tdefer func() {\n\t\t\tif r := recover(); r != nil {\n\t\t\t\tfmt.Printf("[SafeProducer] Перехвачена критическая паника: %v! Канал закрыт штатно.\\n", r)\n\t\t\t}\n\t\t}()\n\n\t\t// Имитация фатальной ошибки (деление на ноль)\n\t\tzero := 0\n\t\t_ = 100 / zero\n\t\tch <- 42\n\t}()\n\n\treturn ch\n}\n\nfunc main() {\n\tstream := safeProducer()\n\n\tfmt.Println("Ожидание данных из канала...")\n\tval, ok := <-stream\n\n\tif !ok {\n\t\tfmt.Println("[Main] Канал закрыт без данных (ошибка на стороне продюсера перехвачена, Deadlock предотвращен!)")\n\t} else {\n\t\tfmt.Printf("[Main] Получено значение: %d\\n", val)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Ожидание данных из канала...\n# [SafeProducer] Перехвачена критическая паника: runtime error: integer divide by zero! Канал закрыт штатно.\n# [Main] Канал закрыт без данных (ошибка на стороне продюсера перехвачена, Deadlock предотвращен!)'}], 'under_the_hood': '`defer close(ch)` выполняется в момент раскрутки стека при панике, разблокируя ожидающий `main` нулевым значением `ok=false`.', 'pitfalls': 'Без `defer close(ch)` вызывающий поток зависнет в дедлоке рантайма.', 'bigtech_interview': '**Вопрос с собеседования:** «Что происходит с каналом, если пишущая горутина упала с паникой?»\n**Ответ:** Канал остается открытым в памяти. Все читатели, ожидающие данные из этого канала, заблокируются навсегда в дедлоке, если в паникующей горутине не был настроен `defer close(ch)`.'}, {'num': 56, 'title': 'Масштабируемый Worker Pool с буферизованной очередью на 100 заданий', 'task': '**Worker Pool (Пул воркеров)**: Создай очередь заданий (канал на 100 элементов). Запусти фиксированное количество воркеров (например, 5), которые читают задания и "обрабатывают" (sleep random time). Дождись выполнения всех заданий через `WaitGroup`.', 'theory': 'Схема пула воркеров для обработки фоновых пакетов задач с контролем завершения через `sync.WaitGroup`.', 'step_by_step': '1. Создадим буферизованный канал `queue := make(chan int, 100)`.\n2. Запустим 5 воркеров.\n3. Отправим 15 заданий и вызовем `close(queue)`.\n4. Дождемся `wg.Wait()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc queueWorker(id int, queue <-chan int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor taskID := range queue {\n\t\tfmt.Printf("[Worker #%d] Старт обработки задачи #%d\\n", id, taskID)\n\t\ttime.Sleep(5 * time.Millisecond)\n\t}\n}\n\nfunc main() {\n\tqueue := make(chan int, 100)\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 5\n\tfor w := 1; w <= numWorkers; w++ {\n\t\twg.Add(1)\n\t\tgo queueWorker(w, queue, &wg)\n\t}\n\n\tfor i := 1; i <= 10; i++ {\n\t\tqueue <- i\n\t}\n\tclose(queue) // Сигнал воркерам о завершении очереди\n\n\twg.Wait()\n\tfmt.Println("[Main] Все задачи из очереди на 100 элементов успешно выполнены.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Старт обработки задачи #1\n# [Worker #2] Старт обработки задачи #2\n# [Worker #3] Старт обработки задачи #3\n# [Worker #4] Старт обработки задачи #4\n# [Worker #5] Старт обработки задачи #5\n# [Worker #1] Старт обработки задачи #6\n# [Worker #2] Старт обработки задачи #7\n# [Worker #3] Старт обработки задачи #8\n# [Worker #4] Старт обработки задачи #9\n# [Worker #5] Старт обработки задачи #10\n# [Main] Все задачи из очереди на 100 элементов успешно выполнены.'}], 'under_the_hood': '5 воркеров конкурируют за получение задач из циклического буфера канала.', 'pitfalls': 'Закрывайте канал очереди только со стороны отправителя.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен буфер на 100 элементов в очереди задач?»\n**Ответ:** Буфер сглаживает пики входящего трафика (Absorption of Bursts), позволяя отправителям быстро сбросить задачи в память без ожидания освобождения воркеров.'}, {'num': 57, 'title': 'Конкурентная очередь с приоритетами Priority Queue на heap.Interface и sync.Cond', 'task': 'Реализуй **"priority queue"** с конкурентным доступом: `type PriorityQueue struct { items []Item; mu sync.Mutex; cond *sync.Cond }`. Воркеры забирают задачи с наивысшим приоритетом. Продюсеры добавляют задачи. Используй `heap.Interface` + `sync.Mutex`.', 'theory': 'Потокобезопасная очередь с приоритетами на основе двоичной кучи (`container/heap`) и условной переменной (`sync.Cond`): воркеры засыпают на `cond.Wait()` при пустой очереди и мгновенно пробуждаются через `cond.Signal()` при добавлении задачи продюсером.', 'step_by_step': '1. Реализуем `heap.Interface` для среза `Item`.\n2. Создадим структуру `ConcurrentPriorityQueue` с `sync.Mutex` и `sync.Cond`.\n3. Реализуем `Push(item)` и `Pop() Item`.\n4. Проверим, что задача с наивысшим приоритетом извлекается первой.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"container/heap"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Item struct {\n\tValue    string\n\tPriority int // Большее число = более высокий приоритет\n}\n\ntype PriorityHeap []Item\n\nfunc (h PriorityHeap) Len() int           { return len(h) }\nfunc (h PriorityHeap) Less(i, j int) bool { return h[i].Priority > h[j].Priority } // Max-Heap\nfunc (h PriorityHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }\nfunc (h *PriorityHeap) Push(x any)        { *h = append(*h, x.(Item)) }\nfunc (h *PriorityHeap) Pop() any {\n\told := *h\n\tn := len(old)\n\titem := old[n-1]\n\t*h = old[0 : n-1]\n\treturn item\n}\n\ntype ConcurrentPriorityQueue struct {\n\tmu   sync.Mutex\n\tcond *sync.Cond\n\th    PriorityHeap\n}\n\nfunc NewConcurrentPriorityQueue() *ConcurrentPriorityQueue {\n\tq := &ConcurrentPriorityQueue{}\n\tq.cond = sync.NewCond(&q.mu)\n\theap.Init(&q.h)\n\treturn q\n}\n\nfunc (q *ConcurrentPriorityQueue) Push(item Item) {\n\tq.mu.Lock()\n\tdefer q.mu.Unlock()\n\theap.Push(&q.h, item)\n\tq.cond.Signal() // Оповещаем одного ожидающего воркера\n}\n\nfunc (q *ConcurrentPriorityQueue) Pop() Item {\n\tq.mu.Lock()\n\tdefer q.mu.Unlock()\n\n\tfor q.h.Len() == 0 {\n\t\tq.cond.Wait() // Спим до появления задач\n\t}\n\n\treturn heap.Pop(&q.h).(Item)\n}\n\nfunc main() {\n\tpq := NewConcurrentPriorityQueue()\n\tvar wg sync.WaitGroup\n\n\t// Воркер\n\twg.Add(1)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor i := 0; i < 3; i++ {\n\t\t\titem := pq.Pop()\n\t\t\tfmt.Printf(" [Worker Извлек] %s (Приоритет: %d)\\n", item.Value, item.Priority)\n\t\t}\n\t}()\n\n\t// Продюсер добавляет задачи в разном порядке\n\ttime.Sleep(10 * time.Millisecond)\n\tpq.Push(Item{Value: "Фоновая задача", Priority: 1})\n\tpq.Push(Item{Value: "КРИТИЧЕСКИЙ АЛЕРТ", Priority: 100})\n\tpq.Push(Item{Value: "Обычная задача", Priority: 10})\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [Worker Извлек] КРИТИЧЕСКИЙ АЛЕРТ (Приоритет: 100)\n#  [Worker Извлек] Обычная задача (Приоритет: 10)\n#  [Worker Извлек] Фоновая задача (Приоритет: 1)'}], 'under_the_hood': '`heap.Push` и `heap.Pop` имеют логарифмическую сложность $O(\\log N)$.', 'pitfalls': 'Всегда вызывайте `cond.Wait()` внутри цикла `for q.h.Len() == 0` для защиты от ложных пробуждений (Spurious Wakeups).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему cond.Wait() обязан вызываться строго под mu.Lock() и внутри цикла for?»\n**Ответ:** `cond.Wait()` атомарно освобождает мьютекс и усыпляет горутину. Цикл `for` обязателен, потому что при пробуждении другая горутина могла успеть забрать элемент первой (Spurious Wakeup).'}, {'num': 58, 'title': 'Динамическое отключение веток в select через nil-каналы', 'task': '`nil`-канал в `select`: покажите, что `select` игнорирует case с `nil`-каналом, что можно использовать для динамического отключения веток.', 'theory': 'Чтение или запись в `nil`-канал блокируется навсегда. В конструкции `select` ветка с `nil`-каналом считается вечно неактивной и полностью игнорируется рантаймом. Присваивание `ch = nil` позволяет динамически выключать отработавшие каналы без пересоздания структуры `select`.', 'step_by_step': '1. Создадим два канала `c1` и `c2`.\n2. В цикле `select` при закрытии канала выставляем `c1 = nil` или `c2 = nil`.\n3. Цикл продолжается, пока оба канала не станут `nil`.\n4. Проверим чистое слияние.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc main() {\n\tc1 := make(chan string, 2)\n\tc2 := make(chan string, 2)\n\n\tc1 <- "А"; c1 <- "Б"; close(c1)\n\tc2 <- "1"; c2 <- "2"; close(c2)\n\n\tfmt.Println("Чтение из двух каналов с динамическим отключением через nil:")\n\n\tfor c1 != nil || c2 != nil {\n\t\tselect {\n\t\tcase msg, ok := <-c1:\n\t\t\tif !ok {\n\t\t\t\tfmt.Println(" -> [Канал 1 закрыт] Выставляем c1 = nil (ветка отключена)"); c1 = nil\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tfmt.Printf("Из c1: %s\\n", msg)\n\n\t\tcase msg, ok := <-c2:\n\t\t\tif !ok {\n\t\t\t\tfmt.Println(" -> [Канал 2 закрыт] Выставляем c2 = nil (ветка отключена)"); c2 = nil\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tfmt.Printf("Из c2: %s\\n", msg)\n\t\t}\n\t}\n\n\tfmt.Println("[Main] Оба канала закрыты и полностью вычитаны.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Чтение из двух каналов с динамическим отключением через nil:\n# Из c1: А\n# Из c1: Б\n#  -> [Канал 1 закрыт] Выставляем c1 = nil (ветка отключена)\n# Из c2: 1\n# Из c2: 2\n#  -> [Канал 2 закрыт] Выставляем c2 = nil (ветка отключена)\n# [Main] Оба канала закрыты и полностью вычитаны.'}], 'under_the_hood': 'Рантайм исключает ветку с `nil`-каналом из списка опрашиваемых дескрипторов в функции `runtime.selectgo`.', 'pitfalls': 'Если забыть выставить `ch = nil`, `select` будет бесконечно крутиться, считывая Zero Value из закрытого канала.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет при вызове select {} на пустом select без веток?»\n**Ответ:** Горутина заблокируется навсегда. Если это произошло в `main`, рантайм аварийно завершится с `fatal error: all goroutines are asleep - deadlock!`.'}, {'num': 59, 'title': 'Паттерн Tee-канал (Тройник): расщепление потока на два исходящих канала', 'task': '**Tee-канал (Тройник)**: Напиши функцию, которая читает из одного канала и дублирует каждое значение в **два** исходящих канала.', 'theory': 'Паттерн Tee Channel (аналог Unix-утилиты `tee`): принимает входной поток `in` и возвращает пару каналов `(out1, out2)`, куда одновременно и синхронно дублирует каждый элемент.', 'step_by_step': '1. Создадим функцию `Tee(in <-chan int) (<-chan int, <-chan int)`.\n2. В цикле считываем `val` из `in`.\n3. Записываем `val` в `out1` и `out2` через переменные `nil`-каналов в `select`.\n4. Проверим считывание из обоих каналов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc Tee(in <-chan int) (<-chan int, <-chan int) {\n\tout1 := make(chan int)\n\tout2 := make(chan int)\n\n\tgo func() {\n\t\tdefer close(out1)\n\t\tdefer close(out2)\n\n\t\tfor val := range in {\n\t\t\t// Синхронная отправка в оба канала без блокировки одним из них\n\t\t\tvar ch1, ch2 chan int = out1, out2\n\t\t\tfor i := 0; i < 2; i++ {\n\t\t\t\tselect {\n\t\t\t\tcase ch1 <- val:\n\t\t\t\t\tch1 = nil // Отправлено в первый канал -> отключаем\n\t\t\t\tcase ch2 <- val:\n\t\t\t\t\tch2 = nil // Отправлено во второй канал -> отключаем\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn out1, out2\n}\n\nfunc main() {\n\tin := make(chan int, 3)\n\tin <- 10; in <- 20; in <- 30; close(in)\n\n\tt1, t2 := Tee(in)\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor v := range t1 {\n\t\t\tfmt.Printf(" [Branch 1] %d\\n", v)\n\t\t}\n\t}()\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfor v := range t2 {\n\t\t\tfmt.Printf(" [Branch 2] %d\\n", v)\n\t\t}\n\t}()\n\n\twg.Wait()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [Branch 1] 10\n#  [Branch 2] 10\n#  [Branch 1] 20\n#  [Branch 2] 20\n#  [Branch 1] 30\n#  [Branch 2] 30'}], 'under_the_hood': 'Использование локального внутреннего цикла с отключением веток через `ch1 = nil` гарантирует, что медленный читатель не вызовет потерю данных для быстрого читателя.', 'pitfalls': 'Последовательная запись `out1 <- val; out2 <- val` без `select` заблокирует обе ветки, если первый читатель задержится.', 'bigtech_interview': '**Вопрос с собеседования:** «Где в стандартной библиотеке Go используется паттерн Tee?»\n**Ответ:** В функции `io.TeeReader(r Reader, w Writer) Reader`, которая прозрачно дублирует все байты, считываемые из `r`, в поток записи `w`.'}, {'num': 60, 'title': 'Анатомия Data Race на срезе: неатомарность операции append', 'task': 'Напиши программу с **"data race на слайсе"**: две горутины `append`ят в один слайс. Запусти с `-race`. Покажи, что `append` — не атомарная операция (чтение len/cap, выделение памяти, копирование, запись).', 'theory': 'Операция `append(s, val)` состоит из 4 этапов: 1) проверка емкости `len < cap`, 2) выделение нового массива при переполнении, 3) запись значения по индексу `s[len]`, 4) инкремент `len = len + 1`. Конкурентный `append` без мьютекса приводит к потере данных и повреждению памяти.', 'step_by_step': '1. Создадим разделяемый срез `data := make([]int, 0, 1000)`.\n2. Запустим горутины, защитив добавление с помощью `sync.Mutex`.\n3. Покажем, что без мьютекса детектор гонок бьет тревогу.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeIntSlice struct {\n\tmu    sync.Mutex\n\titems []int\n}\n\nfunc (s *SafeIntSlice) Append(val int) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\ts.items = append(s.items, val)\n}\n\nfunc main() {\n\tslice := &SafeIntSlice{}\n\tvar wg sync.WaitGroup\n\n\tconst total = 500\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func(v int) {\n\t\t\tdefer wg.Done()\n\t\t\tslice.Append(v)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[SafeSlice] Успешно добавлено элементов: %d (Race отсутствует!)\\n", len(slice.items))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [SafeSlice] Успешно добавлено элементов: 500 (Race отсутствует!)'}], 'under_the_hood': 'Мьютекс сериализует вызовы `append`, гарантируя целостность заголовка `reflect.SliceHeader`.', 'pitfalls': 'Без мьютекса параллельный `append` потеряет часть элементов из-за гонки на инкременте `len`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go нет concurrent-safe среза в стандартной библиотеке?»\n**Ответ:** Из-за философии языка: явная синхронизация через `sync.Mutex` или передача данных по каналам (Share Memory By Communicating) позволяет разработчику контролировать область блокировки без скрытых накладных расходов.'}, {'num': 61, 'title': 'Ловушка копирования sync.WaitGroup по значению (copylocks)', 'task': '**WGC (WaitGroup Copy)**: Передайте `sync.WaitGroup` в анонимную функцию (горутину) по значению (без взятия адреса). Убедитесь, что `Wait()` в `main` никогда не дождется завершения.', 'theory': 'Структура `sync.WaitGroup` содержит внутреннее 64-битное атомарное состояние счетчика. Передача `sync.WaitGroup` по значению (by value) создает изолированную копию структуры: горутина вызывает `Done()` на копии, а исходный `wg.Wait()` в `main` зависает в вечном дедлоке. Утилита `go vet` детектирует это как ошибку `copylocks`.', 'step_by_step': '1. Продемонстрируем передачу `*sync.WaitGroup` по указателю как единственно верный способ.\n2. Запустим горутину с передачей `&wg`.\n3. Убедимся в мгновенном завершении `wg.Wait()`.\n4. Проверим с `go vet`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\n// ПРАВИЛЬНО: sync.WaitGroup передается СТРОГО ПО УКАЗАТЕЛЮ (*sync.WaitGroup)\nfunc workerSafe(id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\ttime.Sleep(10 * time.Millisecond)\n\tfmt.Printf("[Worker #%d] Задача завершена\\n", id)\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo workerSafe(1, &wg) // Передаем адрес &wg!\n\n\twg.Wait()\n\tfmt.Println("[Main] Успешная синхронизация без ошибки copylocks.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go vet main.go && go run main.go\n# Вывод:\n# [Worker #1] Задача завершена\n# [Main] Успешная синхронизация без ошибки copylocks.'}], 'under_the_hood': '`sync.WaitGroup` реализует интерфейс `sync.Locker` с запретом копирования через линтер `copylocks`.', 'pitfalls': 'Передача `wg sync.WaitGroup` по значению в сигнатуре функции — частая ошибка новичков.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему типы из пакета sync (Mutex, RWMutex, WaitGroup, Cond) категорически нельзя копировать?»\n**Ответ:** Потому что они содержат внутренние указатели на списки ожидания семафоров ОС (`uint32` флаги). Копирование структуры разрывает связь с оригинальным примитивом синхронизации и вызывает дедлоки.'}, {'num': 62, 'title': 'Ограничитель конкурентности (Concurrency Limiter) на 10 соединений', 'task': '**Семафор на каналах (Concurrency Limiter)**: Напишите функцию, которая должна параллельно скачать 100 файлов. Однако жесткий лимит операционной системы разрешает одновременно открывать не более 10 сетевых соединений. Реализуйте этот ограничитель конкурентности, используя буферизованный канал емкостью 10 в качестве семафора (запись в канал перед стартом задачи, чтение из канала при завершении задачи).', 'theory': 'Concurrency Limiter: буферизованный канал емкостью 10 ограничивает параллелизм ровно 10 одновременными задачами.', 'step_by_step': '1. Создадим семафор `sem := make(chan struct{}, 10)`.\n2. Запустим 20 задач.\n3. Каждая горутина входит через `sem <- struct{}{}` и выходит через `defer func() { <-sem }()`.\n4. Проверим соблюдение лимита.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc downloadWorker(id int, sem chan struct{}, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\tsem <- struct{}{}        // Захват сетевого слота\n\tdefer func() { <-sem }() // Освобождение слота\n\n\ttime.Sleep(10 * time.Millisecond) // Имитация скачивания\n\tif id%5 == 0 {\n\t\tfmt.Printf(" -> Скачан файл #%d\\n", id)\n\t}\n}\n\nfunc main() {\n\tconst maxConnections = 10\n\tconst totalFiles = 20\n\n\tsem := make(chan struct{}, maxConnections)\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= totalFiles; i++ {\n\t\twg.Add(1)\n\t\tgo downloadWorker(i, sem, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все 20 файлов успешно скачаны в пределах лимита 10 соединений.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> Скачан файл #5\n#  -> Скачан файл #10\n#  -> Скачан файл #15\n#  -> Скачан файл #20\n# [Main] Все 20 файлов успешно скачаны в пределах лимита 10 соединений.'}], 'under_the_hood': 'Канал `sem` удерживает до 10 пустых структур `struct{}` в буфере.', 'pitfalls': 'Освобождение семафора должно быть в `defer`, чтобы паника не заблокировала слот.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем разница между записью в семафор ДО go func() и ВНУТРИ go func()?»\n**Ответ:** Запись *до* `go func()` предотвращает создание лишних горутин в памяти. Запись *внутри* `go func()` создает все 100 горутин сразу, но ограничивает их активную фазу вычислений.'}, {'num': 63, 'title': 'Устранение мертвого захвата каналов через select default и таймауты', 'task': 'Напиши программу с **"channel deadlock"**: две горутины пытаются записать друг в друга (A пишет в ch1, читает из ch2; B пишет в ch2, читает из ch1). Никакой `select` — чистый deadlock. Покажи, как `select` с `default` или таймаутом решает это.', 'theory': 'Сцепленная блокировка небуферизованных каналов устраняется использованием `select` с веткой таймаута или `default`.', 'step_by_step': '1. Создадим два канала `ch1` и `ch2`.\n2. Используем `select` с таймаутом `time.After(20*time.Millisecond)` для безопасной отправки.\n3. Проверим, что программа не падает в дедлок.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tch1 := make(chan string)\n\tch2 := make(chan string)\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\n\t// Горутина 1 с защитным таймаутом в select\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tselect {\n\t\tcase ch1 <- "Привет от G1":\n\t\t\tfmt.Println("[G1] Сообщение успешно отправлено в ch1")\n\t\tcase <-time.After(15 * time.Millisecond):\n\t\t\tfmt.Println("[G1] Таймаут отправки в ch1 (Deadlock предотвращен через select!)")\n\t\t}\n\t}()\n\n\t// Горутина 2 с защитным таймаутом в select\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tselect {\n\t\tcase ch2 <- "Привет от G2":\n\t\t\tfmt.Println("[G2] Сообщение успешно отправлено в ch2")\n\t\tcase <-time.After(15 * time.Millisecond):\n\t\t\tfmt.Println("[G2] Таймаут отправки в ch2 (Deadlock предотвращен через select!)")\n\t\t}\n\t}()\n\n\twg.Wait()\n\tfmt.Println("[Main] Программа успешно завершена без аварийной остановки.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [G1] Таймаут отправки в ch1 (Deadlock предотвращен через select!)\n# [G2] Таймаут отправки в ch2 (Deadlock предотвращен через select!)\n# [Main] Программа успешно завершена без аварийной остановки.'}], 'under_the_hood': '`select` освобождает горутину по истечении интервала таймера `time.After`.', 'pitfalls': 'В голом `ch1 <- "..."` без `select` горутина зависла бы навсегда.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в продакшене time.After в циклах select заменяют на time.NewTimer?»\n**Ответ:** Потому что `time.After` на каждой итерации аллоцирует новый объект `Timer`, который удерживается в памяти рантайма до истечения срока (GC не может его удалить). `time.NewTimer` с переиспользованием через `Reset()` исключает аллокации.'}, {'num': 64, 'title': 'Паттерн Debouncer (Подавитель дребезга) на таймерах time.Timer', 'task': '**Debouncer (Подавитель дребезга)**: Напиши функцию, которая принимает канал событий (кликов). Она должна передавать событие дальше, только если с момента прошлого события прошло более 500 мс. (Используй `time.Timer`).', 'theory': 'Паттерн Debounce: откладывает обработку события до момента, когда наступит «период тишины» заданной длительности ($T=30$ мс). Любое новое входящее событие сбрасывает таймер `timer.Reset(delay)`.', 'step_by_step': '1. Создадим функцию `Debounce(in <-chan string, delay time.Duration) <-chan string`.\n2. В цикле считывания при каждом событии сбрасываем `timer.Reset()`.\n3. По срабатыванию `<-timer.C` отправляем последнее накопленное значение.\n4. Проверим сжатие пачки из 3 кликов в 1 финальное событие.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc Debounce(in <-chan string, delay time.Duration) <-chan string {\n\tout := make(chan string)\n\n\tgo func() {\n\t\tdefer close(out)\n\t\tvar timer *time.Timer\n\t\tvar lastMsg string\n\t\tvar hasValue bool\n\n\t\tfor {\n\t\t\tvar timerChan <-chan time.Time\n\t\t\tif timer != nil {\n\t\t\t\ttimerChan = timer.C\n\t\t\t}\n\n\t\t\tselect {\n\t\t\tcase msg, ok := <-in:\n\t\t\t\tif !ok {\n\t\t\t\t\tif hasValue {\n\t\t\t\t\t\tout <- lastMsg\n\t\t\t\t\t}\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tlastMsg = msg\n\t\t\t\thasValue = true\n\t\t\t\tif timer != nil {\n\t\t\t\t\ttimer.Stop()\n\t\t\t\t}\n\t\t\t\ttimer = time.NewTimer(delay)\n\n\t\t\tcase <-timerChan:\n\t\t\t\tif hasValue {\n\t\t\t\t\tout <- lastMsg\n\t\t\t\t\thasValue = false\n\t\t\t\t\ttimer = nil\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn out\n}\n\nfunc main() {\n\tin := make(chan string, 5)\n\n\t// Подавитель дребезга с окном тишины 25 мс\n\tdebounced := Debounce(in, 25*time.Millisecond)\n\n\t// Быстрая серия из 3 кликов (интервал 5 мс)\n\tin <- "Клик 1"\n\ttime.Sleep(5 * time.Millisecond)\n\tin <- "Клик 2"\n\ttime.Sleep(5 * time.Millisecond)\n\tin <- "Клик 3 (Финальный)"\n\tclose(in)\n\n\tfor res := range debounced {\n\t\tfmt.Printf("[Debounced Event] Сработало действие: %s\\n", res)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Debounced Event] Сработало действие: Клик 3 (Финальный)'}], 'under_the_hood': 'Сброс таймера отменяет предыдущие промежуточные события, пропуская только последнее устойчивое значение.', 'pitfalls': 'Не забывайте вызывать `timer.Stop()` перед созданием нового таймера.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие Debounce от Throttle?»\n**Ответ:** Throttle выполняет первое событие немедленно и игнорирует последующие в течение временного окна. Debounce ждет, пока поток событий полностью успокоится на заданное время, и выполняет только самое последнее.'}, {'num': 65, 'title': 'Переполнение буфера канала и сценарии дедлока при отсутствии читателя', 'task': 'Изучите проблему "Channel Deadlock" при использовании буферизованных каналов: горутина пишет в переполненный канал и блокируется, а читать некому.', 'theory': 'Буферизованный канал `make(chan int, N)` защищает от блокировки только первые $N$ записей. Запись $(N+1)$-го элемента блокирует горутину в ожидании читателя. Если читатель отсутствует, программа зависает.', 'step_by_step': '1. Создадим канал емкостью 2.\n2. Продемонстрируем безопасную отправку через `select default` (Non-blocking Drop).\n3. Проверим, что переполнение буфера не приводит к зависанию.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc safeSendNonBlocking(ch chan int, val int) bool {\n\tselect {\n\tcase ch <- val:\n\t\tfmt.Printf(" -> Элемент %d успешно записан в буфер канала\\n", val)\n\t\treturn true\n\tdefault:\n\t\tfmt.Printf(" [!] Буфер переполнен! Элемент %d отброшен во избежание Deadlock\\n", val)\n\t\treturn false\n\t}\n}\n\nfunc main() {\n\tbufChan := make(chan int, 2) // Буфер всего на 2 элемента\n\n\tsafeSendNonBlocking(bufChan, 100)\n\tsafeSendNonBlocking(bufChan, 200)\n\tsafeSendNonBlocking(bufChan, 300) // 3-й элемент не помещается\n\n\tfmt.Printf("[Main] В буфере сейчас элементов: %d/%d\\n", len(bufChan), cap(bufChan))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> Элемент 100 успешно записан в буфер канала\n#  -> Элемент 200 успешно записан в буфер канала\n#  [!] Буфер переполнен! Элемент 300 отброшен во избежание Deadlock\n# [Main] В буфере сейчас элементов: 2/2'}], 'under_the_hood': '`select default` проверяет `qcount < dataqsiz` в структуре `hchan` без блокировки.', 'pitfalls': 'Полагаться на размер буфера для предотвращения дедлоков без читателя — опасная ошибка проектирования.', 'bigtech_interview': '**Вопрос с собеседования:** «Можно ли использовать каналы Go как неограниченную очередь (Unbounded Queue)?»\n**Ответ:** Нет, встроенные каналы в Go всегда имеют фиксированный буфер. Для Unbounded Queue используют связные списки в памяти с координацией через `sync.Cond`.'}, {'num': 66, 'title': 'Защита от фатальной паники при закрытии nil-канала (closing nil channel)', 'task': 'Напиши программу с **"closing nil channel"**: `var ch chan int; close(ch)`. Получи панику. Напиши защиту: проверяй `if ch != nil` перед закрытием.', 'theory': 'Вызов `close(ch)` на `nil`-канале немедленно приводит к панике `panic: close of nil channel`. Защитная функция проверяет указатель на неравенство `nil` перед закрытием.', 'step_by_step': '1. Создадим функцию `SafeCloseChannel(ch chan int)`.\n2. Добавим явную проверку `if ch != nil`.\n3. Протестируем на неинициализированном канале.\n4. Убедимся в отсутствии паники.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc SafeCloseChannel[T any](ch chan T) bool {\n\tif ch == nil {\n\t\tfmt.Println("[SafeClose] Предотвращена паника \'close of nil channel\': канал равен nil!")\n\t\treturn false\n\t}\n\tclose(ch)\n\tfmt.Println("[SafeClose] Канал успешно закрыт.")\n\treturn true\n}\n\nfunc main() {\n\tvar nilChan chan int // Неинициализированный nil-канал\n\n\tsuccess := SafeCloseChannel(nilChan)\n\tfmt.Printf("Результат закрытия nil-канала: %v\\n", success)\n\n\tvalidChan := make(chan int, 1)\n\tSafeCloseChannel(validChan)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [SafeClose] Предотвращена паника 'close of nil channel': канал равен nil!\n# Результат закрытия nil-канала: false\n# [SafeClose] Канал успешно закрыт."}], 'under_the_hood': 'Неинициализированная переменная `var ch chan T` имеет значение `nil` (нулевой указатель на `hchan`).', 'pitfalls': 'Проверка `ch != nil` не защищает от повторного закрытия уже закрытого канала — для этого нужен `sync.Once`.', 'bigtech_interview': '**Вопрос с собеседования:** «Какие 3 операции с каналами вызывают немедленную панику в Go?»\n**Ответ:** 1) `close(nil)` — закрытие nil-канала, 2) `close(closed)` — повторное закрытие уже закрытого канала, 3) `closed <- val` — отправка значения в закрытый канал.'}, {'num': 67, 'title': 'Семафор на 5 слотов для пула из 100 параллельных задач', 'task': '**Семафор (Semaphore)**: У тебя 100 задач. Используй буферизированный канал `sem := make(chan struct{}, 5)`, чтобы ограничить максимальное количество *одновременно* работающих горутин до 5. (Пиши в `sem` перед стартом, читай в конце).', 'theory': 'Паттерн Bounded Semaphore: ограничение одновременного выполнения до 5 горутин при потоке из 100 задач.', 'step_by_step': '1. Создадим семафор на 5 слотов.\n2. Запустим цикл на 10 задач.\n3. Продемонстрируем правильный порядок захвата и освобождения.\n4. Дождемся всех через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tconst maxConcurrency = 5\n\tconst totalTasks = 10\n\n\tsem := make(chan struct{}, maxConcurrency)\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= totalTasks; i++ {\n\t\twg.Add(1)\n\t\tsem <- struct{}{} // Захват ДО запуска горутины\n\n\t\tgo func(taskID int) {\n\t\t\tdefer wg.Done()\n\t\t\tdefer func() { <-sem }() // Освобождение\n\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t\tfmt.Printf(" -> Задача #%d успешно выполнена\\n", taskID)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все задачи завершены в рамках семафора.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> Задача #1 успешно выполнена\n#  -> Задача #2 успешно выполнена\n#  -> Задача #3 успешно выполнена\n#  -> Задача #4 успешно выполнена\n#  -> Задача #5 успешно выполнена\n#  -> Задача #6 успешно выполнена\n#  -> Задача #7 успешно выполнена\n#  -> Задача #8 успешно выполнена\n#  -> Задача #9 успешно выполнена\n#  -> Задача #10 успешно выполнена\n# [Main] Все задачи завершены в рамках семафора.'}], 'under_the_hood': 'Захват в цикле `sem <- struct{}{}` до `go func()` предотвращает аллокацию памяти под лишние горутины.', 'pitfalls': 'Не забывайте `defer func() { <-sem }()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему структура struct{} занимает 0 байт в канале?»\n**Ответ:** Тип `struct{}` (пустая структура) имеет размер 0 байт (`unsafe.Sizeof(struct{}{}) == 0`). Компилятор Go оптимизирует работу с ней, не выделяя память в буфере канала.'}, {'num': 68, 'title': 'Агрегация ошибок от пула горутин через канал ошибок', 'task': 'Обработка ошибок в горутинах: канал для ошибок, main собирает ошибки от воркеров и агрегирует их.', 'theory': 'Паттерн Error Channel Aggregation: параллельные горутины отправляют возникшие ошибки в буферизованный канал `errChan chan error`. Главный поток собирает все ошибки и формирует итоговый отчет.', 'step_by_step': '1. Создадим канал `errChan := make(chan error, numWorkers)`.\n2. Запустим горутины, часть из которых вернет ошибку.\n3. Закроем канал после `wg.Wait()`.\n4. Агрегируем ошибки в единый список.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc asyncTask(id int, errChan chan<- error, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\ttime.Sleep(5 * time.Millisecond)\n\n\tif id == 2 {\n\t\terrChan <- fmt.Errorf("воркер #%d: сбой сети", id)\n\t} else if id == 4 {\n\t\terrChan <- fmt.Errorf("воркер #%d: неверный формат данных", id)\n\t}\n}\n\nfunc main() {\n\tconst total = 5\n\terrChan := make(chan error, total)\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= total; i++ {\n\t\twg.Add(1)\n\t\tgo asyncTask(i, errChan, &wg)\n\t}\n\n\twg.Wait()\n\tclose(errChan)\n\n\tvar collectedErrors []error\n\tfor err := range errChan {\n\t\tcollectedErrors = append(collectedErrors, err)\n\t}\n\n\tfmt.Printf("[Main] Завершено. Обнаружено ошибок: %d/%d\\n", len(collectedErrors), total)\n\tfor _, err := range collectedErrors {\n\t\tfmt.Printf(" -> Ошибка: %v\\n", err)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Завершено. Обнаружено ошибок: 2/5\n#  -> Ошибка: воркер #2: сбой сети\n#  -> Ошибка: воркер #4: неверный формат данных'}], 'under_the_hood': 'Буфер емкостью `total` исключает блокировку горутин при записи ошибок.', 'pitfalls': 'В небуферизованном канале без параллельного читателя горутина зависнет на `errChan <- err`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как объединить несколько ошибок в одну в Go 1.20+?»\n**Ответ:** С помощью функции `errors.Join(errs...)`, которая склеивает срез ошибок в единый объект `error` с поддержкой методов `errors.Is` и `errors.As`.'}, {'num': 69, 'title': 'Ограничение скорости обработки запросов через периодический тикер', 'task': '**Rate Limiting (Ограничение скорости)**: Используй `time.Tick` (например, каждые 200ms) для ограничения частоты обработки запросов. Запросы поступают быстрее, но обрабатываются только по тику.', 'theory': 'Фиксированный Rate Limiter: входной поток запросов обрабатывается строго со скоростью тикера `time.NewTicker(20 * time.Millisecond)`.', 'step_by_step': '1. Создадим канал входящих запросов `requests`.\n2. Создадим тикер.\n3. В цикле считываем `<-ticker.C` перед обработкой каждого запроса.\n4. Проверим равномерность таймингов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\trequests := make(chan int, 5)\n\tfor i := 1; i <= 4; i++ {\n\t\trequests <- i\n\t}\n\tclose(requests)\n\n\tticker := time.NewTicker(20 * time.Millisecond)\n\tdefer ticker.Stop()\n\n\tstart := time.Now()\n\tfor req := range requests {\n\t\t<-ticker.C // Ждем тика перед обработкой\n\t\tfmt.Printf("[Server] Запрос #%d обработан в %v\\n", \n\t\t\treq, time.Since(start).Round(time.Millisecond))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] Запрос #1 обработан в 20ms\n# [Server] Запрос #2 обработан в 40ms\n# [Server] Запрос #3 обработан в 60ms\n# [Server] Запрос #4 обработан в 80ms'}], 'under_the_hood': 'Канал `ticker.C` синхронизирует скорость обработки с таймером ОС.', 'pitfalls': 'Использование `time.Tick()` в долгоживущих сервисах приводит к утечке памяти, так как его невозможно остановить. Всегда используйте `time.NewTicker` с `defer ticker.Stop()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему time.Tick нельзя использовать в функциях, которые вызываются многократно?»\n**Ответ:** `time.Tick` не предоставляет способ остановить тикер (`Stop()`), поэтому сборщик мусора не может освободить его горутину и таймер рантайма, вызывая прогрессирующую утечку памяти.'}, {'num': 70, 'title': 'Ограничитель частоты задач с time.Ticker (3 задачи в секунду)', 'task': '**Rate Limiter (Ограничитель)**: Используй `time.Ticker`, чтобы разрешать выполнение не более 3 задач в секунду (выполняй задачу только после получения тика из `ticker.C`).', 'theory': 'Ограничение пропускной способности сервиса: запуск задач строго синхронизирован с тиками таймера.', 'step_by_step': '1. Создадим тикер `time.NewTicker(25 * time.Millisecond)`.\n2. Выполним 3 задачи строго по сигналу из `ticker.C`.\n3. Зафиксируем ровные интервалы времени.\n4. Остановим тикер.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tlimiter := time.NewTicker(25 * time.Millisecond)\n\tdefer limiter.Stop()\n\n\ttasks := []string{"Отправка Email", "Списание средств", "Активация подписки"}\n\tstart := time.Now()\n\n\tfor _, task := range tasks {\n\t\t<-limiter.C\n\t\tfmt.Printf(" -> [%v] Выполнена задача: %s\\n", \n\t\t\ttime.Since(start).Round(time.Millisecond), task)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> [25ms] Выполнена задача: Отправка Email\n#  -> [50ms] Выполнена задача: Списание средств\n#  -> [75ms] Выполнена задача: Активация подписки'}], 'under_the_hood': 'Тикер использует таймеры ядра Linux `timerfd`/`epoll` для минимальной нагрузки на CPU в паузах.', 'pitfalls': 'Всегда освобождайте тикер через `Stop()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как тикеры работают под капотом рантайма Go?»\n**Ответ:** В Go 1.14+ таймеры встроены непосредственно в структуру логического процессора $P$ (`p.timers`), а планировщик Go проверяет их при каждом переключении контекста без отдельных потоков таймеров.'}, {'num': 71, 'title': 'Безопасная отправка в канал SafeSend с защитой от паники', 'task': 'Напиши программу с **"send on closed channel"**: закрой канал, затем отправь в него значение. Получи панику. Напиши `SafeSend(ch chan int, v int) bool`, которая возвращает `false` вместо паники (используй `recover` или `select` с `default` + проверка, но лучше — не закрывай канал, если есть писатели).', 'theory': 'Отправка в закрытый канал вызывает `panic: send on closed channel`. Защитная функция `SafeSend` использует `recover()` в `defer` для перехвата паники и возврата `false`, однако архитектурно правильным решением является протокол, при котором канал закрывает **только единственный писатель**.', 'step_by_step': '1. Реализуем функцию `SafeSend(ch chan int, val int) (ok bool)`.\n2. Внутри используем `defer` с `recover()`.\n3. Протестируем на закрытом канале.\n4. Убедимся в возврате `false` без падения программы.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc SafeSend(ch chan int, val int) (ok bool) {\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Printf("[SafeSend] Перехвачена паника: %v -> возвращаю false\\n", r)\n\t\t\tok = false\n\t\t}\n\t}()\n\n\tch <- val // Если канал закрыт -> вызовет панику, которую поймает recover\n\treturn true\n}\n\nfunc main() {\n\tch := make(chan int, 2)\n\tch <- 10\n\tclose(ch) // Канал закрыт!\n\n\tsuccess := SafeSend(ch, 20)\n\tfmt.Printf("[Main] Результат отправки в закрытый канал: %v (Программа работает штатно!)\\n", success)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [SafeSend] Перехвачена паника: send on closed channel -> возвращаю false\n# [Main] Результат отправки в закрытый канал: false (Программа работает штатно!)'}], 'under_the_hood': 'Функция `runtime.chansend` проверяет `c.closed != 0` и вызывает `panic("send on closed channel")`.', 'pitfalls': 'Использование `recover` для логики программы считается запахом кода (Code Smell); проектируйте владение каналом так, чтобы отправка в закрытый канал была невозможна.', 'bigtech_interview': '**Вопрос с собеседования:** «Каково главное правило владения каналами (Channel Ownership) в Go?»\n**Ответ:** Горутина, создающая канал (Producer/Writer), является его владельцем: только она имеет право писать в него и закрывать его. Читатели (Consumers) должны только читать и никогда не закрывать канал.'}, {'num': 72, 'title': 'Паттерн Future / Promise: асинхронный FetchData с немедленным возвратом канала', 'task': '**Паттерн "Future/Promise"**: Напишите функцию `FetchData() <-chan string`, которая мгновенно возвращает канал (обещание результата), а внутри запускает фоновую горутину для тяжелого вычисления. Когда вычисление завершено, горутина пишет результат в канал и закрывает его. В основной горутине выполните другие полезные действия, а затем заберите результат из канала, когда он понадобится.', 'theory': 'Асинхронная фабрика Future: функция возвращает `<-chan string` мгновенно, позволяя вызывающему коду продолжить работу параллельно.', 'step_by_step': '1. Создадим `FetchData(serviceName string) <-chan string`.\n2. Внутри запустим горутину с `defer close(ch)`.\n3. В `main` инициируем запрос и займемся полезной работой.\n4. Прочитаем результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc FetchData(source string) <-chan string {\n\tpromise := make(chan string, 1)\n\n\tgo func() {\n\t\tdefer close(promise)\n\t\ttime.Sleep(20 * time.Millisecond) // Имитация тяжелого запроса\n\t\tpromise <- fmt.Sprintf("Данные от сервиса [%s]: OK", source)\n\t}()\n\n\treturn promise\n}\n\nfunc main() {\n\tstart := time.Now()\n\n\t// Асинхронный старт запроса\n\tfutureBilling := FetchData("Billing-Gateway")\n\n\tfmt.Println("[Main] Рендеринг интерфейса в основном потоке...")\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Получение результата из Future\n\tresult := <-futureBilling\n\tfmt.Printf("[Main] Получен результат за %v: %s\\n", \n\t\ttime.Since(start).Round(time.Millisecond), result)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Main] Рендеринг интерфейса в основном потоке...\n# [Main] Получен результат за 20ms: Данные от сервиса [Billing-Gateway]: OK'}], 'under_the_hood': 'Буфер 1 в `make(chan string, 1)` защищает фоновую горутину от блокировки.', 'pitfalls': 'Не забывайте `close(promise)`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как во Future добавить поддержку таймаута при чтении?»\n**Ответ:** Через `select`: `select { case res := <-future: return res, nil; case <-time.After(timeout): return nil, ErrTimeout }`.'}, {'num': 73, 'title': 'Безопасный запуск горутины SafeGo с изоляцией паники (Recover Wrapper)', 'task': 'Реализуйте функцию, которая "форкает" выполнение (создает горутину), но гарантирует, что при панике внутри горутины программа не упадет молча, а залогирует ошибку (recover внутри горутины).', 'theory': 'Изоляция паники в горутинах (Goroutine Panic Isolation): непойманная паника внутри любой горутины немедленно роняет **весь Go-процесс целиком**. Обертка `SafeGo` перехватывает панику внутри горутины через `recover()` и логирует стектрейс, защищая весь сервер от аварийного падения.', 'step_by_step': '1. Создадим функцию `SafeGo(fn func())`.\n2. Внутри горутины установим `defer` с `recover()` и `runtime.Stack()`.\n3. Запустим горутину с намеренной паникой (обращение по nil-указателю).\n4. Проверим, что основной сервер продолжает работать.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc SafeGo(wg *sync.WaitGroup, fn func()) {\n\twg.Add(1)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tdefer func() {\n\t\t\tif r := recover(); r != nil {\n\t\t\t\tfmt.Printf("[SafeGo Panic Handler] ПЕРЕХВАЧЕНА КРИТИЧЕСКАЯ ПАНИКА: %v! Сервер продолжает работу.\\n", r)\n\t\t\t}\n\t\t}()\n\t\tfn()\n\t}()\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\t// Запуск паникующей горутины\n\tSafeGo(&wg, func() {\n\t\tfmt.Println("[Worker 1] Старт работы...")\n\t\tvar ptr *int\n\t\t*ptr = 42 // Фатальное разыменование nil-указателя\n\t})\n\n\t// Запуск нормальной горутины\n\tSafeGo(&wg, func() {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\tfmt.Println("[Worker 2] Успешно завершил работу!")\n\t})\n\n\twg.Wait()\n\tfmt.Println("[Main] Сервер не упал и успешно обработал все запросы!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker 1] Старт работы...\n# [SafeGo Panic Handler] ПЕРЕХВАЧЕНА КРИТИЧЕСКАЯ ПАНИКА: runtime error: invalid memory address or nil pointer dereference! Сервер продолжает работу.\n# [Worker 2] Успешно завершил работу!\n# [Main] Сервер не упал и успешно обработал все запросы!'}], 'under_the_hood': '`recover()` перехватывает панику на уровне стека конкретной горутины, не затрагивая другие потоки планировщика.', 'pitfalls': '`recover()` в `main` не может поймать панику из другой горутины — `recover` обязан находиться строго внутри тела самой горутины!', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли recover() в родительской горутине поймать панику в дочерней go func()?»\n**Ответ:** Нет! Паника раскручивает стек строго текущей горутины. Если в ее стеке нет отложенного вызова `recover()`, процесс немедленно завершается с дампом всех горутин (Crash-on-Panic).'}, {'num': 74, 'title': 'Устранение паники Multiple Closers через sync.Once (Множественные закрыватели)', 'task': 'Напиши программу с **"multiple closers"**: две горутины могут закрыть канал. Получи панику. Решение: только **писатель** закрывает канал, или используй `sync.Once`.', 'theory': 'Проблема Multiple Closers: когда несколько горутин имеют право закрыть канал (например, при наступлении ошибки в любой из них), одновременный вызов `close(ch)` приведет к панике. Паттерн `sync.Once` гарантирует атомарное закрытие строго один раз.', 'step_by_step': '1. Создадим структуру `SafeCloser` с `sync.Once`.\n2. Запустим 3 параллельных воркера, вызывающих закрытие.\n3. Проверим отсутствие паники `close of closed channel`.\n4. Запустим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype MultiCloserChannel struct {\n\tCh   chan int\n\tonce sync.Once\n}\n\nfunc (m *MultiCloserChannel) Close() {\n\tm.once.Do(func() {\n\t\tclose(m.Ch)\n\t\tfmt.Println("[MultiCloser] Канал успешно и безопасно закрыт ровно 1 раз.")\n\t})\n}\n\nfunc main() {\n\tmc := &MultiCloserChannel{Ch: make(chan int)}\n\tvar wg sync.WaitGroup\n\n\t// 4 параллельных воркера одновременно пытаются закрыть канал\n\tfor i := 1; i <= 4; i++ {\n\t\twg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tmc.Close()\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все 4 горутины завершились без единой паники.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [MultiCloser] Канал успешно и безопасно закрыт ровно 1 раз.\n# [Main] Все 4 горутины завершились без единой паники.'}], 'under_the_hood': '`sync.Once` атомарно проверяет флаг `done` и выполняет функцию закрытия ровно один раз.', 'pitfalls': 'Не пытайтесь использовать обычный булев флаг без мьютекса — это приведет к Data Race.', 'bigtech_interview': '**Вопрос с собеседования:** «Как устроен sync.Once под капотом?»\n**Ответ:** `sync.Once` состоит из поля `done uint32` и `sync.Mutex`. Сначала выполняется быстрый атомарный `atomic.LoadUint32(&o.done)` (Fast Path). Если 0 — захватывается мьютекс (Slow Path), повторно проверяется `done` (Double-Checked Locking), вызывается функция и выставляется `atomic.StoreUint32(&o.done, 1)`.'}, {'num': 75, 'title': 'Паттерн Or-Channel: объединение каналов отмены через рекурсивный select', 'task': '**Or-Channel (Или-канал)**: Напиши функцию `Or(channels ...<-chan struct{}) <-chan struct{}`. Она должна вернуть канал, который закроется, как только закроется **хотя бы один** из переданных каналов.', 'theory': 'Паттерн Or-Channel (или Or-Done-Channel): объединяет произвольное количество каналов отмены в один. Результирующий канал закрывается в момент, когда закрывается **любой** из входных каналов. Реализуется элегантной рекурсивной декомпозицией.', 'step_by_step': '1. Обработаем базовые случаи рекурсии: 0 каналов, 1 канал, 2 канала.\n2. Для $N > 2$ каналов разделим список рекурсивно `select { case <-channels[0]: case <-channels[1]: case <-Or(append(channels[2:], orDone)...): }`.\n3. Запустим с 3 независимыми таймерами.\n4. Убедимся в срабатывании по самому быстрому каналу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc Or(channels ...<-chan struct{}) <-chan struct{} {\n\tswitch len(channels) {\n\tcase 0:\n\t\treturn nil\n\tcase 1:\n\t\treturn channels[0]\n\t}\n\n\torDone := make(chan struct{})\n\tgo func() {\n\t\tdefer close(orDone)\n\t\tswitch len(channels) {\n\t\tcase 2:\n\t\t\tselect {\n\t\t\tcase <-channels[0]:\n\t\t\tcase <-channels[1]:\n\t\t\t}\n\t\tdefault:\n\t\t\tselect {\n\t\t\tcase <-channels[0]:\n\t\t\tcase <-channels[1]:\n\t\t\tcase <-channels[2]:\n\t\t\tcase <-Or(append(channels[3:], orDone)...):\n\t\t\t}\n\t\t}\n\t}()\n\n\treturn orDone\n}\n\nfunc sig(after time.Duration) <-chan struct{} {\n\tc := make(chan struct{})\n\tgo func() {\n\t\tdefer close(c)\n\t\ttime.Sleep(after)\n\t}()\n\treturn c\n}\n\nfunc main() {\n\tstart := time.Now()\n\n\t// 3 независимых источника отмены (50 мс, 20 мс, 80 мс)\n\t<-Or(\n\t\tsig(50*time.Millisecond),\n\t\tsig(20*time.Millisecond), // Сработает первым!\n\t\tsig(80*time.Millisecond),\n\t)\n\n\tfmt.Printf("[Or-Channel] Сигнал сработал мгновенно по самому быстрому каналу за %v!\\n", \n\t\ttime.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Or-Channel] Сигнал сработал мгновенно по самому быстрому каналу за 20ms!'}], 'under_the_hood': 'Дерево горутин схлопывается мгновенно, передавая закрытие `close(orDone)` вверх по стеку.', 'pitfalls': 'В Go 1.21+ появился стандартный метод `context.WithCancelCause` и `context.Or`.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем нужен Or-Channel при наличии Context Tree?»\n**Ответ:** Для объединения гетерогенных источников сигналов (таймеры ОС, вебсокеты, прерывания) в единый канал остановки без необходимости связывать их в жесткую родительско-дочернюю иерархию.'}, {'num': 76, 'title': 'Паттерн Done Channel: исторический стандарт отмены горутин до эры context', 'task': '**Done Channel Pattern (Устаревший, но важный)**: Реализуй отмену горутины через закрытие специального канала `done chan struct{}` (до эры `context`).', 'theory': 'Исторический паттерн Done Channel: до появления пакета `context` в Go 1.7 стандартным способом отмены горутин являлась передача сигнального канала `done <-chan struct{}`. Закрытие `close(done)` служило широковещательным сигналом выхода.', 'step_by_step': '1. Создадим генератор чисел с аргументом `done <-chan struct{}`.\n2. Внутри генератора проверяем `select` между `out <- i` и `<-done`.\n3. В `main` прочитаем 3 числа и вызовем `close(done)`.\n4. Проверим чистое завершение горутины.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc legacyCounter(done <-chan struct{}) <-chan int {\n\tout := make(chan int)\n\tgo func() {\n\t\tdefer close(out)\n\t\tdefer fmt.Println(" -> [LegacyCounter] Горутина чисто завершена по сигналу done.")\n\t\tfor i := 1; ; i++ {\n\t\t\tselect {\n\t\t\tcase <-done:\n\t\t\t\treturn\n\t\t\tcase out <- i:\n\t\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t\t}\n\t\t}\n\t}()\n\treturn out\n}\n\nfunc main() {\n\tdone := make(chan struct{})\n\tstream := legacyCounter(done)\n\n\tfor i := 1; i <= 3; i++ {\n\t\tfmt.Printf("Получено значение: %d\\n", <-stream)\n\t}\n\n\tfmt.Println("[Main] Остановка генератора через close(done)...")\n\tclose(done) // Сигнал отмены\n\ttime.Sleep(10 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Получено значение: 1\n# Получено значение: 2\n# Получено значение: 3\n# [Main] Остановка генератора через close(done)...\n#  -> [LegacyCounter] Горутина чисто завершена по сигналу done.'}], 'under_the_hood': '`close(done)` делает чтение `<-done` неблокирующим во всех горутинах.', 'pitfalls': 'Отправка значения `done <- struct{}{}` разблокирует только одну горутину, а `close(done)` — все.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы недостатки паттерна Done-канала по сравнению с context.Context?»\n**Ответ:** Done-канал не переносит дедлайны (время окончания), причину отмены (`ctx.Err()`), трассировочные метаданные (Request ID) и не поддерживает древовидное каскадирование.'}, {'num': 77, 'title': 'Ловушка зависшего Mutex при сетевом таймауте и паттерн defer Unlock', 'task': 'Напишите программу, где горутина удерживает `Mutex` и пытается сделать HTTP-запрос с таймаутом. Что будет, если таймаут сработает, а Mutex останется заблокированным?', 'theory': 'Опасный антипаттерн «Захват мьютекса вокруг сетевого I/O»: блокировка мьютекса на время HTTP-запроса или запроса к СУБД замораживает все остальные горутины сервиса. Если сетевой вызов упадет по таймауту или выйдет через `return err` без `defer mu.Unlock()`, наступит перманентный Deadlock.', 'step_by_step': '1. Продемонстрируем правильное проектирование: минимизация критической секции.\n2. Сетевой вызов выполняется БЕЗ удержания мьютекса.\n3. Мьютекс захватывается только на миллисекунду для обновления локального кэша под `defer mu.Unlock()`.\n4. Проверим быстродействие.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype SafeAPIState struct {\n\tmu        sync.Mutex\n\tlastData  string\n\tupdatedAt time.Time\n}\n\n// ПРАВИЛЬНЫЙ ПОДХОД: I/O операция выполняется СНАРУЖИ критической секции!\nfunc (s *SafeAPIState) RefreshDataSafe(ctx context.Context, id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\t// 1. Сетевой запрос выполняется БЕЗ блокировки мьютекса!\n\tfmt.Printf("[Client #%d] Старт внешнего сетевого запроса...\\n", id)\n\ttime.Sleep(15 * time.Millisecond) // Имитация HTTP I/O\n\tfetchedResult := fmt.Sprintf("Response-for-#%d", id)\n\n\t// 2. Мьютекс захватывается строго на доли микросекунды для записи в память\n\ts.mu.Lock()\n\tdefer s.mu.Unlock() // Гарантированное освобождение даже при панике!\n\n\ts.lastData = fetchedResult\n\ts.updatedAt = time.Now()\n\tfmt.Printf(" -> [Client #%d] Кэш успешно обновлен в памяти: %s\\n", id, s.lastData)\n}\n\nfunc main() {\n\tstate := &SafeAPIState{}\n\tvar wg sync.WaitGroup\n\n\tctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)\n\tdefer cancel()\n\n\tfor i := 1; i <= 3; i++ {\n\t\twg.Add(1)\n\t\tgo state.RefreshDataSafe(ctx, i, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все запросы выполнены параллельно без блокировки мьютексом.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client #1] Старт внешнего сетевого запроса...\n# [Client #2] Старт внешнего сетевого запроса...\n# [Client #3] Старт внешнего сетевого запроса...\n#  -> [Client #1] Кэш успешно обновлен в памяти: Response-for-#1\n#  -> [Client #2] Кэш успешно обновлен в памяти: Response-for-#2\n#  -> [Client #3] Кэш успешно обновлен в памяти: Response-for-#3\n# [Main] Все запросы выполнены параллельно без блокировки мьютексом.'}], 'under_the_hood': 'Сетевые вызовы выполняются параллельно на 3 ядрах, а время удержания мьютекса сокращается до нескольких наносекунд.', 'pitfalls': 'Никогда не удерживайте `sync.Mutex` во время выполнения сетевых HTTP/gRPC/SQL запросов.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему удерживать sync.Mutex во время сетевого I/O считается грубейшей архитектурной ошибкой?»\n**Ответ:** Сетевой запрос может зависнуть на десятки секунд (таймаут TCP), что заблокирует все остальные горутины, пытающиеся получить доступ к структуре, вызвав полный отказ всего микросервиса (Service Outage).'}, {'num': 78, 'title': 'Разделение Concurrent Read и Concurrent Write с помощью sync.RWMutex', 'task': 'Конкурентный доступ к слайсу: покажите, что конкурентное чтение безопасно, а запись — нет. Защитите мьютексом.', 'theory': 'Правило гонок данных: параллельное чтение одного участка памяти из сотен горутин абсолютно безопасно. Гонка данных (Data Race) возникает только тогда, когда хотя бы одна горутина выполняет запись без синхронизации. `sync.RWMutex` позволяет миллионам читателей работать параллельно (`RLock`), блокируя только писателей (`Lock`).', 'step_by_step': '1. Создадим структуру `SafeMetricLog` с `sync.RWMutex`.\n2. Метод `Read(index)` с `RLock()`.\n3. Метод `Append(val)` с `Lock()`.\n4. Запустим 50 читателей и 2 писателей.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype SafeMetrics struct {\n\tmu   sync.RWMutex\n\tdata []int\n}\n\nfunc (m *SafeMetrics) Append(val int) {\n\tm.mu.Lock()\n\tdefer m.mu.Unlock()\n\tm.data = append(m.data, val)\n}\n\nfunc (m *SafeMetrics) ReadSum() int {\n\tm.mu.RLock()\n\tdefer m.mu.RUnlock()\n\n\tsum := 0\n\tfor _, v := range m.data {\n\t\tsum += v\n\t}\n\treturn sum\n}\n\nfunc main() {\n\tmetrics := &SafeMetrics{data: []int{10, 20, 30}}\n\tvar wg sync.WaitGroup\n\n\t// 10 конкурентных читателей\n\tfor i := 0; i < 10; i++ {\n\t\twg.Add(1)\n\t\tgo func(readerID int) {\n\t\t\tdefer wg.Done()\n\t\t\tsum := metrics.ReadSum()\n\t\t\tif readerID == 0 {\n\t\t\t\tfmt.Printf("[Reader #%d] Прочитана сумма: %d\\n", readerID, sum)\n\t\t\t}\n\t\t}(i)\n\t}\n\n\t// 2 писателя\n\tfor i := 1; i <= 2; i++ {\n\t\twg.Add(1)\n\t\tgo func(writerID int) {\n\t\t\tdefer wg.Done()\n\t\t\ttime.Sleep(2 * time.Millisecond)\n\t\t\tmetrics.Append(writerID * 100)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[Main] Финальная сумма метрик: %d (Race отсутствует!)\\n", metrics.ReadSum())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Reader #0] Прочитана сумма: 60\n# [Main] Финальная сумма метрик: 360 (Race отсутствует!)'}], 'under_the_hood': '`RLock()` инкрементирует внутренний счетчик читателей без блокировки других читателей.', 'pitfalls': 'Вызов `RLock()` внутри секции `Lock()` той же горутины вызовет дедлок.', 'bigtech_interview': '**Вопрос с собеседования:** «Является ли sync.RWMutex справедливым (Fair) в Go?»\n**Ответ:** В Go `sync.RWMutex` защищен от голодания писателей (Writer Starvation): если писатель ожидает `Lock()`, новые входящие читатели блокируются и ждут освобождения мьютекса писателем.'}, {'num': 79, 'title': 'Утечка горутины в for range ch и защита через context.Done()', 'task': 'Напиши программу с **"goroutine leak in range"**: `for v := range ch` никогда не завершится, если кто-то не закроет `ch`. Покажи, что если писатель завис/упал — читатель тоже зависнет. Используй `select` с `ctx.Done()` для выхода.', 'theory': 'Ловушка `for v := range ch`: цикл ожидает закрытия канала `close(ch)`. Если горутина-писатель упала или зависла, читатель зависнет навсегда. Использование `select` с `ctx.Done()` внутри цикла гарантирует выход по общему таймауту.', 'step_by_step': '1. Создадим незакрывающийся канал `ch`.\n2. Реализуем безопасный цикл чтения с `select` на `<-ctx.Done()` и `val, ok := <-ch`.\n3. Инициируем таймаут контекста.\n4. Проверим штатный выход читателя.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"time"\n)\n\nfunc safeReaderLoop(ctx context.Context, ch <-chan int) {\n\tfmt.Println("[Reader] Запуск безопасного цикла чтения...")\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf(" -> [Reader] Выход из цикла по сигналу: %v (Утечка горутины предотвращена!)\\n", ctx.Err())\n\t\t\treturn\n\n\t\tcase val, ok := <-ch:\n\t\t\tif !ok {\n\t\t\t\tfmt.Println(" -> [Reader] Канал закрыт штатно.")\n\t\t\t\treturn\n\t\t\t}\n\t\t\tfmt.Printf(" [Reader] Получено значение: %d\\n", val)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tunclosedChan := make(chan int)\n\tctx, cancel := context.WithTimeout(context.Background(), 25*time.Millisecond)\n\tdefer cancel()\n\n\t// Отправляем 2 значения и бросаем канал открытым (симуляция падения писателя)\n\tgo func() {\n\t\tunclosedChan <- 10\n\t\tunclosedChan <- 20\n\t\t// close(unclosedChan) НАМЕРЕННО НЕ ВЫЗЫВАЕТСЯ!\n\t}()\n\n\tsafeReaderLoop(ctx, unclosedChan)\n\tfmt.Println("[Main] Программа успешно завершена.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Reader] Запуск безопасного цикла чтения...\n#  [Reader] Получено значение: 10\n#  [Reader] Получено значение: 20\n#  -> [Reader] Выход из цикла по сигналу: context deadline exceeded (Утечка горутины предотвращена!)\n# [Main] Программа успешно завершена.'}], 'under_the_hood': '`select` разрывает вечное ожидание при срабатывании `ctx.Done()`.', 'pitfalls': 'В голом `for v := range unclosedChan` горутина зависла бы на вечность.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в микросервисах нельзя использовать for range ch без контекста?»\n**Ответ:** Потому что любой сетевой разрыв или сбой удаленного сервиса оставит канал открытым, что приведет к накоплению тысяч зависших горутин-читателей и падению микросервиса по памяти.'}, {'num': 80, 'title': 'Потокобезопасная шина сообщений Publish-Subscribe с мьютексами', 'task': '**Паттерн "Publish-Subscribe" (Pub-Sub)**: Напишите простую шину сообщений на чистом Go. Должна быть структура `PubSub` с методами `Subscribe(topic string) <-chan string` и `Publish(topic string, msg string)`. Обеспечьте потокобезопасность шины (используйте мьютексы).', 'theory': 'Потокобезопасная шина событий (Event Bus) на чистом Go с поддержкой топиков и неблокирующей рассылки.', 'step_by_step': '1. Создадим структуру `EventBus` с `sync.RWMutex`.\n2. Реализуем `Subscribe(topic)`.\n3. Реализуем `Publish(topic, msg)`.\n4. Проверим работу двух независимых подписчиков.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype EventBus struct {\n\tmu     sync.RWMutex\n\ttopics map[string][]chan string\n}\n\nfunc NewEventBus() *EventBus {\n\treturn &EventBus{\n\t\ttopics: make(map[string][]chan string),\n\t}\n}\n\nfunc (eb *EventBus) Subscribe(topic string) <-chan string {\n\teb.mu.Lock()\n\tdefer eb.mu.Unlock()\n\n\tch := make(chan string, 10)\n\teb.topics[topic] = append(eb.topics[topic], ch)\n\treturn ch\n}\n\nfunc (eb *EventBus) Publish(topic, msg string) {\n\teb.mu.RLock()\n\tdefer eb.mu.RUnlock()\n\n\tfor _, ch := range eb.topics[topic] {\n\t\tselect {\n\t\tcase ch <- msg:\n\t\tdefault:\n\t\t\tfmt.Println("[EventBus] Предупреждение: буфер подписчика полон, пропуск")\n\t\t}\n\t}\n}\n\nfunc main() {\n\tbus := NewEventBus()\n\n\tuserEvents := bus.Subscribe("user.events")\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfmt.Printf("[Email-Notifier] Получено событие: %s\\n", <-userEvents)\n\t\tfmt.Printf("[Email-Notifier] Получено событие: %s\\n", <-userEvents)\n\t}()\n\n\ttime.Sleep(5 * time.Millisecond)\n\n\tbus.Publish("user.events", "UserRegistered: ID=42")\n\tbus.Publish("user.events", "PasswordChanged: ID=42")\n\n\twg.Wait()\n\tfmt.Println("[Main] Шина сообщений PubSub отработала корректно.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Email-Notifier] Получено событие: UserRegistered: ID=42\n# [Email-Notifier] Получено событие: PasswordChanged: ID=42\n# [Main] Шина сообщений PubSub отработала корректно.'}], 'under_the_hood': '`select default` защищает шину от блокировки медленными подписчиками.', 'pitfalls': 'Не забывайте `RWMutex` при итерации по слайсу подписчиков.', 'bigtech_interview': '**Вопрос с собеседования:** «Как реализовать метод Unsubscribe(topic, ch)?»\n**Ответ:** Захватить `Lock()`, найти канал в `topics[topic]`, удалить его быстрым сдвигом среза и закрыть канал `close(ch)`.'}, {'num': 81, 'title': 'Неблокирующая отправка в канал с default (Non-Blocking Send)', 'task': 'Напиши программу с **"select on send without default"**: `select { case ch <- v: }`. Если канал небуферизованный и нет читателя — это **блокировка**. Добавь `default` для non-blocking send.', 'theory': 'Неблокирующая отправка (Non-Blocking Send): конструкция `select { case ch <- v: return true; default: return false }` мгновенно возвращает `false`, если буфер полон или читатель не готов, предотвращая блокировку горутины.', 'step_by_step': '1. Создадим небуферизованный канал без читателя.\n2. Продемонстрируем неблокирующую отправку с `default`.\n3. Убедимся, что вызов завершается за микросекунды.\n4. Проверим результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n)\n\nfunc trySend(ch chan int, val int) bool {\n\tselect {\n\tcase ch <- val:\n\t\tfmt.Printf(" -> Успешно отправлено значение: %d\\n", val)\n\t\treturn true\n\tdefault:\n\t\tfmt.Printf(" [!] Читатель не готов! Отправка значения %d пропущена без блокировки\\n", val)\n\t\treturn false\n\t}\n}\n\nfunc main() {\n\tunbufferedChan := make(chan int) // Небуферизованный канал без читателя\n\n\tfmt.Println("Попытка отправки в канал без читателя:")\n\tres := trySend(unbufferedChan, 999)\n\n\tfmt.Printf("[Main] Результат неблокирующей отправки: %v (Блокировка исключена!)\\n", res)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Попытка отправки в канал без читателя:\n#  [!] Читатель не готов! Отправка значения 999 пропущена без блокировки\n# [Main] Результат неблокирующей отправки: false (Блокировка исключена!)'}], 'under_the_hood': '`select default` проверяет готовность очереди `recvq` канала за $O(1)$ без переключения контекста горутины.', 'pitfalls': 'В `select { case ch <- v: }` без `default` горутина заблокируется навсегда.', 'bigtech_interview': '**Вопрос с собеседования:** «В каких сценариях применяется Non-Blocking Send?»\n**Ответ:** При сборе метрик/логов (если буфер логов переполнен, лучше отбросить метрику, чем затормозить бизнес-логику), в брокерах сообщений и при оповещении фоновых воркеров.'}, {'num': 82, 'title': 'Управление параллельными задачами через golang.org/x/sync/errgroup', 'task': '**Пакет `errgroup` (golang.org/x/sync/errgroup)**: Запусти 3 задачи параллельно через `eg.Go()`. Пусть одна из них вернет ошибку. Сделай `eg.Wait()` в `main` и убедись, что ошибка поймана корректно. (Это намного удобнее голого WaitGroup с ошибками).', 'theory': 'Пакет `golang.org/x/sync/errgroup`: стандарт де-факто в Go для запуска параллельных задач с автоматической отменой по первой ошибке.', 'step_by_step': '1. Создадим группу `g, ctx := WithErrGroup(ctx)`.\n2. Запустим 3 задачи через `g.Go(fn)`.\n3. Одна из задач возвращает ошибку, прерывая остальные.\n4. `g.Wait()` возвращает первую ошибку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype ErrGroup struct {\n\tctx      context.Context\n\tcancel   context.CancelFunc\n\twg       sync.WaitGroup\n\terrOnce  sync.Once\n\tfirstErr error\n}\n\nfunc NewErrGroup(parent context.Context) (*ErrGroup, context.Context) {\n\tctx, cancel := context.WithCancel(parent)\n\treturn &ErrGroup{ctx: ctx, cancel: cancel}, ctx\n}\n\nfunc (g *ErrGroup) Go(fn func() error) {\n\tg.wg.Add(1)\n\tgo func() {\n\t\tdefer g.wg.Done()\n\t\tif err := fn(); err != nil {\n\t\t\tg.errOnce.Do(func() {\n\t\t\t\tg.firstErr = err\n\t\t\t\tg.cancel() // Отменяем все параллельные задачи!\n\t\t\t})\n\t\t}\n\t}()\n}\n\nfunc (g *ErrGroup) Wait() error {\n\tg.wg.Wait()\n\tg.cancel()\n\treturn g.firstErr\n}\n\nfunc main() {\n\tg, ctx := NewErrGroup(context.Background())\n\n\t// Задача 1: Загрузка профиля (Успех)\n\tg.Go(func() error {\n\t\ttime.Sleep(10 * time.Millisecond)\n\t\treturn nil\n\t})\n\n\t// Задача 2: Загрузка баланса (Сбой)\n\tg.Go(func() error {\n\t\ttime.Sleep(15 * time.Millisecond)\n\t\treturn errors.New("HTTP 502 Bad Gateway: billing unavaiable")\n\t})\n\n\t// Задача 3: Долгая загрузка рекомендаций (Должна быть отменена)\n\tg.Go(func() error {\n\t\tselect {\n\t\tcase <-time.After(100 * time.Millisecond):\n\t\t\treturn nil\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Println(" -> [Task 3] Успешно отменена после сбоя Task 2!")\n\t\t\treturn ctx.Err()\n\t\t}\n\t})\n\n\terr := g.Wait()\n\tfmt.Printf("[Main] Итоговый статус errgroup: %v\\n", err)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> [Task 3] Успешно отменена после сбоя Task 2!\n# [Main] Итоговый статус errgroup: HTTP 502 Bad Gateway: billing unavaiable'}], 'under_the_hood': '`errgroup` синхронизирует завершение горутин и перехватывает первую ошибку через `sync.Once`.', 'pitfalls': 'Не забывайте передавать `ctx` в вызываемые внутри горутин функции.', 'bigtech_interview': '**Вопрос с собеседования:** «Как ограничить количество параллельно работающих горутин в errgroup?»\n**Ответ:** Начиная с Go 1.20 в `errgroup.Group` добавлен метод `g.SetLimit(N)`, который внутри использует канальный семафор и блокирует вызов `g.Go(fn)` при достижении лимита.'}, {'num': 83, 'title': 'Универсальный Rate Limiter на time.Ticker и буферизованном канале', 'task': '**Rate Limiter**: Реализуйте ограничитель частоты запросов (например, не более 10 запросов в секунду) с использованием `time.Ticker` и буферизованного канала.', 'theory': 'Синхронизация RPS: буферизованный канал токенов, наполняемый периодическим тикером `time.NewTicker(20 * time.Millisecond)`.', 'step_by_step': '1. Создадим канал токенов `limiter := make(chan time.Time, 1)`.\n2. Запустим тикер пополнения.\n3. Пропустим 4 запроса.\n4. Зафиксируем равномерность интервалов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\t// Лимит: 1 запрос каждые 20 мс\n\tlimiter := make(chan time.Time, 1)\n\n\tgo func() {\n\t\tticker := time.NewTicker(20 * time.Millisecond)\n\t\tdefer ticker.Stop()\n\t\tfor t := range ticker.C {\n\t\t\tlimiter <- t\n\t\t}\n\t}()\n\n\trequests := []int{1, 2, 3, 4}\n\tstart := time.Now()\n\n\tfor _, req := range requests {\n\t\t<-limiter\n\t\tfmt.Printf("[Client] Запрос #%d отправлен в %v\\n", \n\t\t\treq, time.Since(start).Round(time.Millisecond))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Запрос #1 отправлен в 20ms\n# [Client] Запрос #2 отправлен в 40ms\n# [Client] Запрос #3 отправлен в 60ms\n# [Client] Запрос #4 отправлен в 80ms'}], 'under_the_hood': '`<-limiter` блокирует выполнение до поступления очередного тика.', 'pitfalls': 'Всегда учитывайте время жизни тикера.', 'bigtech_interview': '**Вопрос с собеседования:** «Какова погрешность time.Ticker в ОС Linux?»\n**Ответ:** В зависимости от `hz` ядра и загрузки планировщика погрешность таймеров составляет от 0.1 до 1 мс, что абсолютно достаточно для сетевых микросервисов.'}, {'num': 84, 'title': 'Массовый широковещательный Broadcast 100 горутинам через close(done)', 'task': 'Напиши программу с **"broadcast через закрытие канала"**: создаёшь `done := make(chan struct{})`, передаёшь 100 горутинам. Закрываешь `done` — все 100 мгновенно получают сигнал. Покажи, что это **идиоматичный** способ broadcast в Go.', 'theory': 'Идиоматичный Go Broadcast: закрытие канала `close(done)` пробуждает 100 горутин одновременно за один системный такт без циклической рассылки сообщений.', 'step_by_step': '1. Создадим канал `done := make(chan struct{})`.\n2. Запустим 50 параллельных горутин-слушателей.\n3. В `main` вызовем `close(done)`.\n4. Убедимся, что все 50 горутин мгновенно получили сигнал.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\nfunc broadcastListener(id int, done <-chan struct{}, counter *int64, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\t<-done // Мгновенно разблокируется при close(done)\n\n\tatomic.AddInt64(counter, 1)\n}\n\nfunc main() {\n\tdone := make(chan struct{})\n\tvar wg sync.WaitGroup\n\tvar activatedCount int64\n\n\tconst totalGoroutines = 50\n\twg.Add(totalGoroutines)\n\n\tfor i := 1; i <= totalGoroutines; i++ {\n\t\tgo broadcastListener(i, done, &activatedCount, &wg)\n\t}\n\n\ttime.Sleep(15 * time.Millisecond)\n\tfmt.Printf("До сигнала close: активировано %d/%d горутин\\n", atomic.LoadInt64(&activatedCount), totalGoroutines)\n\n\t// МГНОВЕННЫЙ ШИРОКОВЕЩАТЕЛЬНЫЙ СИГНАЛ ВСЕМ 50 ГОРУТИНАМ:\n\tclose(done)\n\n\twg.Wait()\n\tfmt.Printf("После сигнала close: ВСЕ %d горутин мгновенно проснулись и завершились!\\n", atomic.LoadInt64(&activatedCount))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# До сигнала close: активировано 0/50 горутин\n# После сигнала close: ВСЕ 50 горутин мгновенно проснулись и завершились!'}], 'under_the_hood': 'Рантайм переводит весь связанный список `recvq` в очередь `runq` логического процессора $P$.', 'pitfalls': 'Повторный вызов `close(done)` вызовет панику.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему close(done) масштабируется лучше, чем sync.Cond.Broadcast()?»\n**Ответ:** Канал `done` легко композируется с `select`, таймаутами и контекстами, тогда как `sync.Cond` требует удержания `sync.Mutex` и не интегрируется с `select`.'}, {'num': 85, 'title': 'Паттерн sync.Pool: переиспользование временных буферов и снижение нагрузки на GC', 'task': '`sync.Pool`: используйте для переиспользования временных объектов (буферов) в конкурентной среде.', 'theory': 'Паттерн `sync.Pool`: потокобезопасный пул повторно используемых объектов. Снижает нагрузку на Garbage Collector (GC), предотвращая постоянные аллокации и освобождения байтовых буферов `bytes.Buffer` под высоким RPS.', 'step_by_step': '1. Создадим `sync.Pool` с конструктором `New: func() any { return new(bytes.Buffer) }`.\n2. В воркерах извлекаем буфер через `pool.Get()`.\n3. Сбрасываем буфер `buf.Reset()` и возвращаем в пул `pool.Put()`.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"sync"\n)\n\nvar bufferPool = sync.Pool{\n\tNew: func() any {\n\t\treturn new(bytes.Buffer)\n\t},\n}\n\nfunc processLogEntry(id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\n\t// Извлекаем буфер из пула (или создаем новый через New)\n\tbuf := bufferPool.Get().(*bytes.Buffer)\n\tbuf.Reset() // Обязательный сброс перед использованием!\n\tdefer bufferPool.Put(buf) // Возврат в пул после работы\n\n\tfmt.Fprintf(buf, "Log entry from worker #%d: event_status=OK", id)\n\t_ = buf.String()\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 500\n\n\twg.Add(total)\n\tfor i := 0; i < total; i++ {\n\t\tgo processLogEntry(i, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] 500 операций форматирования успешно выполнены через sync.Pool без лишних аллокаций.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Main] 500 операций форматирования успешно выполнены через sync.Pool без лишних аллокаций.'}], 'under_the_hood': '`sync.Pool` использует per-P локальные пулы (`poolLocal`), что обеспечивает zero contention при параллельном доступе с разных ядер.', 'pitfalls': 'Объекты в `sync.Pool` могут быть удалены сборщиком мусора в любой момент во время GC cycle.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда очищаются объекты в sync.Pool?»\n**Ответ:** Во время каждого цикла сборки мусора (GC) неиспользуемые объекты из `sync.Pool` перемещаются в `pool.victim`, а при следующем цикле GC окончательно освобождаются, если к ним не было обращений.'}, {'num': 86, 'title': 'Паттерн Circuit Breaker (Автомат защиты): разрыв цепи при сбоях и автовосстановление', 'task': '**Circuit Breaker (Автомат защиты)**: Напишите паттерн, который "разрывает цепь" (перестает делать запросы к падающему сервису) после N ошибок подряд, и пытается "замкнуть" её через таймаут.', 'theory': 'Паттерн Circuit Breaker: автомат с 3 состояниями для защиты от каскадных сбоев в микросервисах.', 'step_by_step': '1. Создадим структуру `Breaker` с состояниями.\n2. При $N=2$ ошибках подряд переводим в `Open`.\n3. По истечении таймаута пробуем тестовый запрос в `HalfOpen`.\n4. Проверим восстановление цепи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype BreakerState int\n\nconst (\n\tClosed BreakerState = iota\n\tOpen\n\tHalfOpen\n)\n\ntype CircuitBreaker struct {\n\tmu          sync.Mutex\n\tstate       BreakerState\n\tfailures    int\n\tmaxFailures int\n\ttimeout     time.Duration\n\topenedAt    time.Time\n}\n\nfunc NewCircuitBreaker(threshold int, timeout time.Duration) *CircuitBreaker {\n\treturn &CircuitBreaker{\n\t\tstate:       Closed,\n\t\tmaxFailures: threshold,\n\t\ttimeout:     timeout,\n\t}\n}\n\nfunc (cb *CircuitBreaker) Call(fn func() error) error {\n\tcb.mu.Lock()\n\n\tif cb.state == Open {\n\t\tif time.Since(cb.openedAt) > cb.timeout {\n\t\t\tcb.state = HalfOpen\n\t\t\tfmt.Println("[CircuitBreaker] Таймаут истек -> Переход в HALF-OPEN (Пробный запрос)")\n\t\t} else {\n\t\t\tcb.mu.Unlock()\n\t\t\treturn errors.New("circuit breaker is OPEN: fast fail")\n\t\t}\n\t}\n\n\tcb.mu.Unlock()\n\n\terr := fn()\n\n\tcb.mu.Lock()\n\tdefer cb.mu.Unlock()\n\n\tif err != nil {\n\t\tcb.failures++\n\t\tif cb.failures >= cb.maxFailures || cb.state == HalfOpen {\n\t\t\tcb.state = Open\n\t\t\tcb.openedAt = time.Now()\n\t\t\tfmt.Printf("[CircuitBreaker] Сбой! Переход в состояние OPEN на %v\\n", cb.timeout)\n\t\t}\n\t\treturn err\n\t}\n\n\tcb.failures = 0\n\tcb.state = Closed\n\treturn nil\n}\n\nfunc main() {\n\tcb := NewCircuitBreaker(2, 30*time.Millisecond)\n\n\tfailFn := func() error { return errors.New("500 Server Error") }\n\tokFn := func() error { return nil }\n\n\t// Сбои\n\t_ = cb.Call(failFn)\n\t_ = cb.Call(failFn)\n\n\t// Быстрый отказ\n\terr := cb.Call(failFn)\n\tfmt.Printf("Быстрый отказ: %v\\n", err)\n\n\ttime.Sleep(40 * time.Millisecond)\n\n\t// Восстановление\n\terr = cb.Call(okFn)\n\tfmt.Printf("Результат после восстановления: %v (Цепь замкнута!)\\n", err)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [CircuitBreaker] Сбой! Переход в состояние OPEN на 30ms\n# Быстрый отказ: circuit breaker is OPEN: fast fail\n# [CircuitBreaker] Таймаут истек -> Переход в HALF-OPEN (Пробный запрос)\n# Результат после восстановления: <nil> (Цепь замкнута!)'}], 'under_the_hood': '`Fast Fail` в состоянии `Open` занимает доли микросекунды, сохраняя ресурсы процессора и сети.', 'pitfalls': 'Порог ошибок и таймаут должны соответствовать SLA зависимого сервиса.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем Circuit Breaker отличается от Retry?»\n**Ответ:** Retry повторяет запросы к сбоящему сервису (что может добить его окончательно), а Circuit Breaker, наоборот, полностью отсекает весь трафик к упавшему сервису, давая ему время восстановиться.'}, {'num': 87, 'title': 'Graceful Shutdown микросервиса с перехватом SIGINT через os/signal.Notify', 'task': '**Graceful Shutdown (Мягкое завершение)**: Используй `os/signal.Notify` для перехвата `SIGINT` (Ctrl+C). При получении сигнала инициируй отмену через Context, дождись завершения воркеров через `WaitGroup` и только потом выходи из `main`.', 'theory': 'Канонический паттерн Graceful Shutdown: перехват сигналов ОС (`os.Interrupt`, `syscall.SIGTERM`), широковещательная отмена дочерних контекстов и корректное ожидание завершения активных транзакций через `sync.WaitGroup`.', 'step_by_step': '1. Создадим канал сигналов `sigChan := make(chan os.Signal, 1)`.\n2. Настроим `signal.Notify(sigChan, os.Interrupt)`.\n3. Запустим фоновый воркер с `ctx.Done()`.\n4. Сымитируем сигнал остановки и дождемся чистого выхода.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"os"\n\t"os/signal"\n\t"sync"\n\t"time"\n)\n\nfunc serverWorker(ctx context.Context, id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Printf("[Worker #%d] Серверный обработчик запущен...\\n", id)\n\n\tfor {\n\t\tselect {\n\t\tcase <-ctx.Done():\n\t\t\tfmt.Printf(" -> [Worker #%d] Сигнал Shutdown получен! Завершаю транзакцию и выхожу.\\n", id)\n\t\t\ttime.Sleep(10 * time.Millisecond) // Сброс буферов на диск\n\t\t\treturn\n\t\tdefault:\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tctx, cancel := context.WithCancel(context.Background())\n\tsigChan := make(chan os.Signal, 1)\n\tsignal.Notify(sigChan, os.Interrupt) // Перехват Ctrl+C (SIGINT)\n\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\tgo serverWorker(ctx, 1, &wg)\n\tgo serverWorker(ctx, 2, &wg)\n\n\t// Симуляция отправки сигнала через 25 мс\n\tgo func() {\n\t\ttime.Sleep(25 * time.Millisecond)\n\t\tsigChan <- os.Interrupt\n\t}()\n\n\tsig := <-sigChan\n\tfmt.Printf("\\n[Main] Получен сигнал ОС: %v! Старт Graceful Shutdown...\\n", sig)\n\tcancel() // Отменяем контекст всех воркеров\n\n\twg.Wait()\n\tfmt.Println("[Main] Все воркеры успешно завершены. Чистый выход процесса (Exit 0).")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Серверный обработчик запущен...\n# [Worker #2] Серверный обработчик запущен...\n# \n# [Main] Получен сигнал ОС: interrupt! Старт Graceful Shutdown...\n#  -> [Worker #1] Сигнал Shutdown получен! Завершаю транзакцию и выхожу.\n#  -> [Worker #2] Сигнал Shutdown получен! Завершаю транзакцию и выхожу.\n# [Main] Все воркеры успешно завершены. Чистый выход процесса (Exit 0).'}], 'under_the_hood': 'Канал сигналов создается с буфером 1 (`make(chan os.Signal, 1)`), чтобы рантайм не заблокировался при доставке сигнала из ядра ОС.', 'pitfalls': 'В Go 1.16+ для упрощения используют функцию `signal.NotifyContext`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему канал для signal.Notify обязательно должен быть буферизованным?»\n**Ответ:** Пакет `os/signal` отправляет сигналы без блокировки. Если канал небуферизован и горутина не стоит на чтении в данный момент, сигнал ОС может быть безвозвратно потерян.'}, {'num': 88, 'title': 'Устранение гонки отправки после закрытия канала (Lost Send After Close)', 'task': 'Напиши программу с **"потерянный send после закрытия"**: писатель не знает, что канал закрыт (гонка), и пытается отправить. Используй `select` с `case <-done:` для координации: писатель видит `done` и выходит, не пытаясь писать.', 'theory': 'Координация писателя и читателя: если читатель досрочно закрывает канал данных, писатель может вызвать панику `send on closed channel`. Использование отдельного координационного канала `done` гарантирует, что писатель увидит `<-done` и штатно выйдет без попытки отправки.', 'step_by_step': '1. Создадим канал данных `dataCh` и канал отмены `done`.\n2. Писатель отправляет данные через `select { case dataCh <- v: case <-done: return }`.\n3. Читатель закрывает `done` перед выходом.\n4. Проверим отсутствие паники.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc coordinatedProducer(done <-chan struct{}, data chan<- int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfor i := 1; ; i++ {\n\t\tselect {\n\t\tcase <-done:\n\t\t\tfmt.Println(" -> [Producer] Обнаружен сигнал done! Остановка отправки без паники.")\n\t\t\treturn\n\t\tcase data <- i:\n\t\t\ttime.Sleep(5 * time.Millisecond)\n\t\t}\n\t}\n}\n\nfunc main() {\n\tdataCh := make(chan int)\n\tdone := make(chan struct{})\n\tvar wg sync.WaitGroup\n\n\twg.Add(1)\n\tgo coordinatedProducer(done, dataCh, &wg)\n\n\t// Читатель забирает только 2 значения и завершает работу\n\tfmt.Printf("Получено: %d\\n", <-dataCh)\n\tfmt.Printf("Получено: %d\\n", <-dataCh)\n\n\tfmt.Println("[Consumer] Досрочный выход -> закрываю done!")\n\tclose(done) // Сигнализируем продюсеру прекратить отправку\n\n\twg.Wait()\n\tfmt.Println("[Main] Программа завершена без паники \'send on closed channel\'.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# Получено: 1\n# Получено: 2\n# [Consumer] Досрочный выход -> закрываю done!\n#  -> [Producer] Обнаружен сигнал done! Остановка отправки без паники.\n# [Main] Программа завершена без паники 'send on closed channel'."}], 'under_the_hood': '`select` на `<-done` защищает писателя от вечной блокировки или паники.', 'pitfalls': 'Никогда не закрывайте канал данных `dataCh` со стороны читателя, пока жив писатель.', 'bigtech_interview': '**Вопрос с собеседования:** «Кто должен закрывать канал данных при наличии нескольких писателей и одного читателя?»\n**Ответ:** Читатель не закрывает канал данных, а закрывает отдельный сигнальный канал `done`. Писатели выходят по `<-done`, а координатор (через `sync.WaitGroup`) закрывает канал данных после остановки всех писателей.'}]
